def _b327_white(c):
    """A progress block in no verdict colour: grey to white, channels within 16."""
    import re as _re
    m = _re.findall(r"[\d.]+", c or "")
    if len(m) < 3: return False
    r, g, b = (float(x) for x in m[:3])
    return max(r, g, b) - min(r, g, b) <= 16 and min(r, g, b) >= 120

def check_b324m_modes(br):
    """Build 324 (b324m): Exam and Review get their own names, marks and
    colours, Instant feedback is gone, and every Begin names its mode.
    "I feel like exam mode and review mode need a new name and logo ...
    Could we make it where the review section is now a purple colored
    icon as well? And exam mode, instead of it being a white for the
    progress bar ... could that color match? ... Let's also remove the
    instant feedback option from the exam mode ... for drill it would say
    begin drill ... For the review one it says show all, it could say
    begin review and if flashcards are on ... the same thing." Exam shows
    as Qualifier and Review as Briefing on every card, sheet, chip, label,
    list and history row, while the stored mode stays "exam"/"review" (an
    old "exam" history entry reads Qualifier); Briefing's mark is the
    flashcards' violet; a Qualifier's progress blocks wear its orange;
    nothing in a Qualifier says right or wrong before the results, even
    with an old Instant feedback preference left on; Begin reads Begin
    drill / Begin qualifier / Begin briefing (flashcards too), and the
    Virtual Room host's reads Open lobby (its button label only - the
    Next pill and the sheet's title are another builder's). Fails on ab75270."""
    print("\n324m. build 324: Qualifier and Briefing, their marks and colours, no Instant feedback, Begin names the mode")
    for label, w, h in DEVICES:
        ctx, pg = booted(br, w, h, seed=USED_ACCOUNT)
        r = pg.evaluate(B324M_MODES)
        ctx.close()
        if r.get("threw"):
            print("   threw:", r["threw"])
        cards = r.get("cards") or {}
        # MOVED IN 326 (b326d): Review again
        # MOVED IN 327: Exam again ("Exams name 'qualifier' is not the move")
        # MOVED IN 327 (b327k): Quiz ("The name 'exam' is not it. I prefer quiz")
        check("%s the mode cards read Drill, Quiz, Review, Virtual Room" % label,
              [cards.get(m, {}).get("title") for m in ("drill", "exam", "review", "vroom")] == ["Drill", "Quiz", "Review", "Virtual Room"],
              [cards.get(m, {}).get("title") for m in ("drill", "exam", "review", "vroom")])
        ed, rd = cards.get("exam", {}).get("desc") or "", cards.get("review", {}).get("desc") or ""
        check("%s the Qualifier card says no feedback until your grade; Briefing's says it is not a test, answers shown" % label,
              "no feedback" in ed and "grade" in ed and "Instant feedback" not in ed
              and rd.startswith("Not a test") and "answer" in rd and "flashcards" in rd, [ed, rd])
        st = {m: cards.get(m, {}).get("stroke") for m in ("drill", "exam", "review", "vroom")}
        # MOVED IN 327: Review's mark is green again, and flashcards' blocks are white
        # ("review flashcards are purple, let's not do that ... just make it green")
        check("%s Review's mark is green, and the flashcards' blocks are white, not violet" % label,
              st["review"] == "rgb(74, 222, 128)" and _b327_white(r.get("flashTick")), [st["review"], r.get("flashTick")])
        check("%s the Qualifier's mark has its own colour, not Drill's, Briefing's or the Virtual Room's" % label,
              st["exam"] and len({st["drill"], st["exam"], st["review"], st["vroom"]}) == 4, st)
        sh = r.get("sheets") or {}
        want = {"drill": ("Drill", "Begin drill"), "exam": ("Quiz", "Begin quiz"),  # MOVED IN 327 (b327k)
                "review": ("Review", "Begin review"), "flash": ("Review", "Begin review")}  # 326: Review again
        for k, (name, begin) in want.items():
            s = sh.get(k) or {}
            check("%s %s sheet: titled %s, the box and the chip say %s, Begin reads %r" % (label, k, name, name, begin),
                  s.get("title") == name and s.get("box") == name and s.get("chip") == name and s.get("begin") == begin,
                  {x: s.get(x) for x in ("title", "box", "chip", "begin")})
        ex = sh.get("exam") or {}
        check("%s no Instant feedback anywhere in the Qualifier's sheet" % label,
              bool(ex) and "Instant feedback" not in (ex.get("sheetText") or "x Instant feedback") and not any("feedback" in t for t in ex.get("rows") or []),
              ex.get("rows"))
        check("%s each sheet's box carries its mode's mark in its colour" % label,
              (sh.get("exam") or {}).get("boxIcon") == st["exam"] and (sh.get("review") or {}).get("boxIcon") == st["review"]
              and (sh.get("drill") or {}).get("boxIcon") == st["drill"],
              {k: (sh.get(k) or {}).get("boxIcon") for k in ("drill", "exam", "review")})
        check("%s the unit-selection pill names the mode: Start drill / qualifier / review (326's name)" % label,
              (sh.get("drill") or {}).get("pill", "").startswith("Start drill,") and (sh.get("exam") or {}).get("pill", "").startswith("Start quiz,")
              and (sh.get("review") or {}).get("pill", "").startswith("Start review,"),
              {k: (sh.get(k) or {}).get("pill") for k in ("drill", "exam", "review")})
        check("%s the Virtual Room host's sheet button reads Open lobby" % label,
              r.get("vrBegin") == "Open lobby",
              {k: r.get(k) for k in ("vrPill", "vrTitle", "vrBegin")})
        run = r.get("run") or {}
        # MOVED IN 327 (b327k): a Quiz run says Quiz; the stored value stays "exam".
        check("%s a Quiz run says Quiz, and cfg, store.opts and runMode keep \"exam\"" % label,
              run.get("label") == "Quiz" and run.get("stored") == "exam" and run.get("mode") == "exam" and run.get("runMode") == "exam"
              and "quiz" in (run.get("counter") or ""),
              {k: run.get(k) for k in ("label", "stored", "mode", "runMode", "counter")})
        # MOVED IN 327: "if you don't know whether you got it right or wrong it should be white"
        check("%s its progress blocks are white, never the Exam's orange (nothing is judged)" % label,
              "is-qualifier" not in (run.get("meterClass") or "") and _b327_white(run.get("done")) and _b327_white(run.get("now")),
              {k: run.get(k) for k in ("meterClass", "done", "now")})
        check("%s nothing says right or wrong before the results, even with an old Instant feedback preference on" % label,
              run.get("judgedWrong") is False and run.get("judgedRight") is False and run.get("changed") is True,
              {k: run.get(k) for k in ("judgedWrong", "judgedRight", "changed", "status")})
        check("%s a Review's list and its flashcards say Review, the list in Review's violet (326's name)" % label,
              r.get("listTitle") == "Review" and r.get("fcLabel") == "Review" and r.get("listIcon") == st["review"],
              {k: r.get(k) for k in ("listTitle", "fcLabel", "listIcon")})
        hi = r.get("hist") or {}
        # MOVED IN 327 (b327k): they read Quiz now, and never Exam or Qualifier.
        check("%s history entries saved as \"exam\" read Quiz (chips, filter, detail, results), still stored as exam" % label,
              hi.get("chips", [])[:2] == ["Quiz", "Quiz"] and "Quiz" in hi.get("filters", [])
              and not re.search(r"Qualifier|\bExam\b", " ".join(hi.get("names", []) + hi.get("filters", []))) and hi.get("detail") == "Quiz"
              and r.get("results") == "Quiz" and hi.get("stored") == ["exam", "exam", "drill"],
              {k: hi.get(k) for k in ("chips", "names", "filters", "detail", "stored")} | {"results": r.get("results")})


# A FIXTURE CODE, never a real one: nothing here reaches Firestore (the
# page runs on the stub), and the code is only ever compared, not printed.
_B324S_CODE = "KQ7W-M4XZ"
_B324S_INIT = "try{localStorage.setItem('class26e.synccode','%s');}catch(e){}" % _B324S_CODE

_B324S_SETTINGS = r"""async (fixture) => {
  const wait = ms => new Promise(r => setTimeout(r, ms));
  const out = {};
  store.seenSettingsTour = true;
  showAppearance(); await wait(900);
  document.querySelectorAll('#tour-overlay, #tour-tooltip').forEach(x => x.remove());
  const de = document.documentElement; de.style.scrollBehavior = 'auto';
  const tab = document.querySelector('.profile-settings-tab');
  if(!tab){ out.err = 'no Settings tab'; return out; }
  const txt = tab.textContent;
  out.fifth = /fifth|5th/i.test(txt);
  out.oldMute = /Mute achievement banners/.test(txt);
  out.oldAdv = /Auto-advance on correct/.test(txt);
  /* every switch title with its description, read off the rows */
  out.rows = [...tab.querySelectorAll('label.opt .otext')].map(t => ({
    title: (t.firstChild && t.firstChild.textContent || '').trim(),
    hint: ((t.querySelector('.ohint') || {}).textContent || '').trim() }));
  /* the tour copy still describes switches that exist */
  const src = String(showAppearance);
  out.tourStale = /keep the screen awake|smooth scrolling|mute banners/i.test(src.slice(src.indexOf('startSimpleTour(')));
  /* the storage field behind the renamed switch is still muteBanners */
  const muteRow = [...tab.querySelectorAll('label.opt')].find(r => /celebrations/i.test(r.textContent));
  if(muteRow){ const was = theme.muteBanners; muteRow.querySelector('input').click(); await wait(60);
    out.muteWired = theme.muteBanners === !was; muteRow.querySelector('input').click(); await wait(60);
    document.querySelectorAll('.toast').forEach(t => t.remove()); }
  /* the code, masked then revealed */
  const row = tab.querySelector('.sync-code-row'), val = tab.querySelector('.sync-code-value');
  if(row && val){
    const well = val.parentElement;
    const box = () => { const r = val.getBoundingClientRect(), w = well.getBoundingClientRect(), cs = getComputedStyle(val);
      return { fs: parseFloat(cs.fontSize), lh: r.height, txt: val.textContent, fam: cs.fontFamily,
        /* the glyphs' centre: the box carries one letter-space after the last character */
        cx: r.left + (r.width - (parseFloat(cs.letterSpacing) || 0)) / 2, wcx: w.left + w.width / 2,
        w: r.width, ww: w.width, wh: w.height, rowH: row.getBoundingClientRect().height,
        own: val.parentElement !== row || r.top > (row.querySelector('.otext') || row).getBoundingClientRect().bottom - 1 }; };
    out.masked = box();
    row.click(); await wait(120);
    out.revealed = box();
    out.revealed.isFixture = out.revealed.txt === fixture;  // compared, never returned
    out.revealed.txt = null; out.masked.txt = out.masked.txt.replace(/[^•-]/g, 'x');
    row.click(); await wait(80);
  }
  /* the section rhythm: every header's gap to the block above it */
  const heads = [...tab.querySelectorAll('.slab.motion-summary')].filter(h => h.offsetParent);
  const blocks = [...tab.querySelectorAll('.settings-card, .sect, .motion-details, .cal-profile-row, .startbar, .sync-note-plain, .more-toggle, .settings-buildline')]
    .filter(e => e.offsetParent && !e.querySelector('.slab.motion-summary'));
  out.heads = heads.map(h => { const r = h.getBoundingClientRect();
    let above = -1e9; blocks.forEach(b => { const q = b.getBoundingClientRect(); if(q.height > 0 && q.bottom <= r.top + 1) above = Math.max(above, q.bottom); });
    let below = 1e9; blocks.forEach(b => { const q = b.getBoundingClientRect(); if(q.height > 0 && q.top >= r.bottom - 1) below = Math.min(below, q.top); });
    return { t: h.firstChild ? String(h.firstChild.textContent).trim() : '', above: Math.round(r.top - above), below: Math.round(below - r.bottom), sync: h.id === 'settings-sync' }; });
  /* every control a finger lands on is at least 44px tall */
  out.small = [...tab.querySelectorAll('button')].filter(b => b.offsetParent && !b.closest('.more-body') && !b.classList.contains('info-icon') && !b.closest('.slab'))
    .map(b => ({ t: b.textContent.trim().slice(0, 24), h: Math.round(b.getBoundingClientRect().height) })).filter(b => b.h < 44);
  out.hscroll = de.scrollWidth > innerWidth + 1;
  return out;
}"""


def check_b324s_settings(br):
    """Build 324 (builder s). Madison: "In settings, the auto advance in
    correct, the title and description are slightly vague. The auto star
    description says every 5th miss or something. Remove that part and
    change it. The mute achievement banners needs to be changed to a
    different more fitting title and description. ... The sync code
    reveal, it's still pretty small when viewing the code. Can we slightly
    enlarge it some more? And finally, the spacing of the stuff under the
    sync code section and beyond is pretty tight."
    So: no "fifth" anywhere on Settings, the old auto-advance and mute
    titles gone and each switch with a description; the renamed switch
    still drives theme.muteBanners; the tour no longer names switches that
    were removed; the revealed code is at least 26px (it was 17.9), on a
    line of its own, centred in a well that is the same height masked or
    revealed, and still one line on a 320px phone; and every section from
    Sync down sits at least as far from the block above it as the sections
    above Sync do (Help and Advanced were 16px against 22). Fails on
    ab75270."""
    print("\n324s. Settings: plain switch copy, a larger sync code, and the rhythm from Sync down")
    for label, w, h in (("iPhone 17 Pro Max", 440, 956), ("iPad Pro 11", 834, 1194), ("320px phone", 320, 568)):
        ctx, pg = booted(br, w, h, seed=USED_ACCOUNT, init=_B324S_INIT)
        try:
            r = pg.evaluate(_B324S_SETTINGS, _B324S_CODE)
            if r.get("err"):
                check("%s Settings could be read at all" % label, False, r["err"]); ctx.close(); continue
            rv, mk = r.get("revealed") or {}, r.get("masked") or {}
            check("%s the revealed code is the account's own code, large (>= 26px), mono, on one line of its own" % label,
                  rv.get("isFixture") and rv.get("fs", 0) >= 26 and "mono" in (rv.get("fam") or "").lower()
                  and rv.get("lh", 99) < rv.get("fs", 0) * 1.6 and rv.get("own") and rv.get("w", 999) <= rv.get("ww", 0),
                  {k: rv.get(k) for k in ("isFixture", "fs", "lh", "own", "w", "ww")})
            check("%s it is centred in its well, and revealing it moves nothing (well %s -> %s px)" % (label, mk.get("wh"), rv.get("wh")),
                  abs(rv.get("cx", 0) - rv.get("wcx", 99)) <= 1.5 and mk.get("wh") is not None and abs(mk.get("wh", 0) - rv.get("wh", 99)) < 0.5
                  and abs(mk.get("rowH", 0) - rv.get("rowH", 99)) < 0.5, [round(rv.get("cx", 0) - rv.get("wcx", 0), 1), mk.get("rowH"), rv.get("rowH")])
            check("%s no sideways scroll" % label, not r.get("hscroll"))
            if w == 320:
                ctx.close(); continue
            check("%s no switch description counts misses ('fifth'), and the old auto-advance and mute titles are gone" % label,
                  not r.get("fifth") and not r.get("oldMute") and not r.get("oldAdv"), [r.get("fifth"), r.get("oldMute"), r.get("oldAdv")])
            rows = r.get("rows") or []
            check("%s every switch has a title and a description" % label,
                  len(rows) >= 6 and all(x["title"] and len(x["hint"]) >= 12 for x in rows), rows)
            check("%s the celebrations switch still sets theme.muteBanners" % label, r.get("muteWired") is True, r.get("muteWired"))
            check("%s the Settings tour does not name switches that were removed" % label, r.get("tourStale") is False)
            heads = r.get("heads") or []
            si = next((i for i, x in enumerate(heads) if x["sync"]), None)
            above_sync = [x["above"] for x in heads[1:si]] if si else []
            from_sync = [x["above"] for x in heads[si:]] if si else []
            floor = min(above_sync) if above_sync else 999
            check("%s every section from Sync down is at least as far from the block above it as the ones above Sync (%s vs %s)"
                  % (label, from_sync, above_sync),
                  bool(from_sync) and len(from_sync) >= 4 and all(g >= floor - 1 for g in from_sync), heads)
            check("%s and every header sits clear of its own content (>= 12px)" % label,
                  all(x["below"] >= 12 for x in heads), [(x["t"], x["below"]) for x in heads])
            check("%s every Settings button is at least 44px tall" % label, not r.get("small"), r.get("small"))
        except Exception as ex:
            check("%s Settings could be driven at all" % label, False, str(ex)[:300])



# The Calendar tab at a fixed date, read off the page. `topics` is put into
# TEST_TOPICS (when the build has it) before the tab is built; null clears it.
B324C_CAL = """async ([iso, topics]) => {
  const wait = ms => new Promise(r => setTimeout(r, ms));
  const RealDate = window.__RealDate || Date; window.__RealDate = RealDate;
  const off = new RealDate(iso + 'T10:00:00').getTime() - RealDate.now();
  window.Date = class extends RealDate { constructor(...a){ if(a.length) super(...a); else super(RealDate.now() + off); }
                                         static now(){ return RealDate.now() + off; } };
  const out = { err: null };
  try{
    out.hasTopics = typeof TEST_TOPICS !== 'undefined';
    if(out.hasTopics){ Object.keys(TEST_TOPICS).forEach(k => delete TEST_TOPICS[k]); if(topics) Object.assign(TEST_TOPICS, topics); }
    showHome(); await wait(250);
    (typeof showCalendarTab === 'function' ? showCalendarTab : showCalendar)(); await wait(700);
    document.querySelectorAll('#tour-overlay, #tour-tooltip, .daily-alert, .toast').forEach(x => x.remove());
    const tab = document.querySelector('#stage > .screen-calendar');
    const txt = el => el ? el.textContent.replace(/\\s+/g, ' ').trim() : null;
    const bg = el => el ? getComputedStyle(el).backgroundColor : null;
    out.tab = !!tab;
    out.lit = [...document.querySelectorAll('#bottomtabs .bottomtab.active')].map(b => b.id);
    /* 1. no List view, no Month / List switcher */
    out.list = { seg: !!(tab && tab.querySelector('.cal-viewseg, .navsegment')), listview: !!(tab && tab.querySelector('.cal-listview, .cal-list, .cal-month-head')),
                 listBtn: !!(tab && [...tab.querySelectorAll('button')].some(b => /^\\s*list\\s*$/i.test(b.textContent))),
                 grid: !!(tab && tab.querySelector('.cal-grid .cal-cell')), day: !!(tab && tab.querySelector('.cal-daycard')) };
    /* what the app's own schedule says about the date */
    const k = todayCalendarKey();
    const entry = CALENDAR_DATA.find(e => e.date === k) || null;
    const nt = CALENDAR_DATA.find(e => e.date >= k && isExamDay(e)) || null;
    out.want = { k, today: entry ? entry.text : null, exam: !!(entry && isExamDay(entry)), when: formatCalendarDate(k),
                 nt: nt ? nt.date : null, ntWhen: nt ? formatCalendarDate(nt.date) : null,
                 days: classDaysRemaining(), tests: testsRemaining() };
    /* 2. Today */
    const t = tab && tab.querySelector('.cal-today-card');
    out.today = t ? { status: txt(t.querySelector('.cal-today-status')), text: txt(t), kind: t.dataset.kind || null,
                      testItems: [...t.querySelectorAll('.cal-sched-item.is-test')].map(txt) } : null;
    /* 3. This week */
    const w = tab && tab.querySelector('.cal-week-card');
    out.week = w ? { days: [...w.querySelectorAll('.cal-week-day')].map(b => ({ d: b.dataset.date, today: b.classList.contains('is-today'),
                       cls: !!b.querySelector('.cal-week-dot:not(.cal-week-dot-test)'), test: !!b.querySelector('.cal-week-dot-test'),
                       testBg: bg(b.querySelector('.cal-week-dot-test')) })),
                     head: txt(w.querySelector('.cal-card-head')) } : null;
    /* 4. Next test */
    const n = tab && tab.querySelector('.cal-nexttest-card');
    out.next = n ? { date: n.dataset.date || null, title: txt(n.querySelector('.cal-nt-title')), when: txt(n.querySelector('.cal-nt-when')),
                     days: (n.querySelector('.cal-nt-count') || { dataset: {} }).dataset.days, num: txt(n.querySelector('.cal-nt-num')),
                     topics: [...n.querySelectorAll('.cal-topics-list li')].map(txt), none: txt(n.querySelector('.cal-topics-none')),
                     posted: txt(n.querySelector('.cal-topics-posted')) } : null;
    /* 5. the remaining counts */
    const c = tab && tab.querySelector('.cal-course-card');
    out.course = c ? { shown: !c.hidden && !!c.getClientRects().length, days: ((txt(c.querySelector('.stx-hero-big')) || '').match(/\d+/) || [null])[0],
                       tiles: c.querySelectorAll('.cal-stat').length, ring: !!c.querySelector('.thx-ring svg') } : null;
    out.order = tab ? [t, w, n, tab.querySelector('.cal-grid')].map(e => e ? Math.round(e.getBoundingClientRect().top + scrollY) : null) : null;
    out.scrollX = document.documentElement.scrollWidth - document.documentElement.clientWidth;
    out.outside = tab ? [...tab.querySelectorAll('.cal-card')].filter(e => { const r = e.getBoundingClientRect(); return r.left < -1 || r.right > innerWidth + 1; }).length : null;
    /* 6. today's test dot, and the key's */
    const tc = document.querySelector('.cal-grid .cal-cell-today');
    out.dot = { today: bg(tc && tc.querySelector('.cal-cell-dot-test')), key: bg(document.querySelector('.cal-legend-dot-test')),
                todaySel: !!(tc && tc.classList.contains('cal-cell-sel')) };
    /* 7. the next test's day in the month */
    if(nt){
      for(let i = 0; i < 12 && !document.querySelector('.cal-cell[data-date="' + nt.date + '"]'); i++){ const b = document.querySelectorAll('.cal-grid-arrow')[1]; if(!b || b.disabled) break; b.click(); await wait(60); }
      const cell = document.querySelector('.cal-cell[data-date="' + nt.date + '"]');
      if(cell){ cell.click(); await wait(200); }
      const dc = document.querySelector('.cal-daycard');
      out.ntDay = { cell: !!cell, topicsCls: !!(cell && document.querySelector('.cal-cell[data-date="' + nt.date + '"]').classList.contains('cal-cell-topics')),
                    topics: dc ? [...dc.querySelectorAll('.cal-topics-list li')].map(txt) : [], none: txt(dc && dc.querySelector('.cal-topics-none')) };
    }
    /* 8. a day tapped in the week is picked in the month too */
    const pick = w && [...w.querySelectorAll('.cal-week-day')].find(b => !b.classList.contains('is-today') && CALENDAR_DATA.some(e => e.date === b.dataset.date && !e.holiday));
    if(pick){
      pick.click(); await wait(300);
      const sel = document.querySelector('.cal-grid .cal-cell-sel');
      const pe = CALENDAR_DATA.find(e => e.date === pick.dataset.date);
      out.pick = { want: pick.dataset.date, sel: sel ? sel.dataset.date : null, card: txt(document.querySelector('.cal-daycard')),
                   entry: pe.text, weekSel: pick.classList.contains('is-sel') };
    }
    /* 9. build 327 round 10: the Settings switch is gone, so the course card
       shows even for a theme that saved it off */
    const was = theme.showClassDaysLeft; theme.showClassDaysLeft = false;
    (typeof showCalendarTab === 'function' ? showCalendarTab : showCalendar)(); await wait(400);
    const c2 = document.querySelector('#stage .cal-course-card');
    out.offHidden = !!c2 && !!c2.getClientRects().length;
    theme.showClassDaysLeft = was;
    if(out.hasTopics) Object.keys(TEST_TOPICS).forEach(k => delete TEST_TOPICS[k]);
  }catch(e){ out.err = String(e && e.message || e); }
  finally{ window.Date = RealDate; }
  return out; }"""


def check_b324c_calendar(br):
    """Build 324 (builder c). Madison: "instead of the list tab, could we
    remove that and maybe really hone in on the calendar we have? ... I want
    it to really feel like the place people go to see what's next up in
    class. If someone asks what's today they go there. Maybe we have a this
    week or this month thing? ... a better way of showing remaining test days
    and class days? I like the way the stat page looks ... We also need to
    incorporate a way to see what's on the next test. She tells us what's on
    it every Sunday." So: no List view and no Month / List switcher; a Today
    card, a This week strip and a Next test card above the month, with the
    right values for a fixed date read off the app's own schedule; the
    remaining counts are classDaysRemaining() / testsRemaining(); TEST_TOPICS
    shows on the Next test card and on that day in the month, and "not
    posted" when it is empty; today's test dot is still the key's amber.
    Fails on ab75270 (Month / List, no cards, no TEST_TOPICS)."""
    print("\n324c. the Calendar tab: no List, Today / This week / Next test, the counts, what's on the next test")
    TOPICS = {"2026-10-19": {"title": "Test #5", "topics": ["Arrest warrants", "Search incident to arrest", "Consent searches"], "postedAt": "2026-10-18"}}
    for dev, w, h in DEVICES:
        ctx, pg = booted(br, w, h, seed=USED_ACCOUNT)
        try:
            # a class day (Tue Oct 13), nothing posted
            a = pg.evaluate(B324C_CAL, ["2026-10-13", None])
            if a.get("err"):
                check("%s: the Calendar tab could be read at all" % dev, False, a["err"])
            L = a.get("list") or {}
            check("%s: no List view and no Month / List switcher; the month and its day card stay" % dev,
                  a.get("tab") and not L.get("seg") and not L.get("listview") and not L.get("listBtn") and L.get("grid") and L.get("day"), L)
            check("%s: the bar's Calendar tab is lit" % dev, a.get("lit") == ["bottomtab-calendar"], a.get("lit"))
            want = a.get("want") or {}
            t = a.get("today") or {}
            check("%s, a class day: the Today card says Class day, the date, and what is on (CCP)" % dev,
                  t.get("status") == "Class day" and want.get("when") in (t.get("text") or "") and "CCP" in (t.get("text") or "")
                  and not t.get("testItems") and "Next" in (t.get("text") or ""), [t, want.get("when")])
            wk = a.get("week") or {}
            days = [d["d"] for d in wk.get("days") or []]
            check("%s: This week is the seven days of today's week (Oct 11-17), today ringed, the test day dotted amber" % dev,
                  days == ["2026-10-%02d" % i for i in range(11, 18)] and [d["d"] for d in wk["days"] if d["today"]] == ["2026-10-13"]
                  and [d["d"] for d in wk["days"] if d["test"]] == ["2026-10-12"]
                  and all(d["testBg"] == "rgb(245, 181, 77)" for d in wk["days"] if d["test"])
                  and [d["d"] for d in wk["days"] if d["cls"]] == ["2026-10-%02d" % i for i in range(12, 17)]
                  and "5 class days" in (wk.get("head") or "") and "1 test" in (wk.get("head") or ""), wk)
            n = a.get("next") or {}
            check("%s: the Next test card is Test #5 on Mon, Oct 19, 6 days to go (the schedule's next exam day)" % dev,
                  want.get("nt") == "2026-10-19" and n.get("date") == "2026-10-19" and n.get("title") == "Test #5"
                  and n.get("when") == want.get("ntWhen") and n.get("days") == "6" and n.get("num") == "6", [n, want])
            # MOVED IN 327 (b327c): "ensure that part is only there if we
            # have the information" - nothing posted means no topics part at
            # all, on the card or that day in the month
            check("%s: nothing posted - no 'On the test' part on the card, nor on that day in the month" % dev,
                  a.get("hasTopics") and not n.get("none") and not n.get("topics")
                  and not ((a.get("ntDay") or {}).get("none")) and not (a.get("ntDay") or {}).get("topics"),
                  [n.get("none"), a.get("ntDay")])
            c = a.get("course") or {}
            check("%s: the course card says classDaysRemaining() class days, by its ring, and nothing else (round 10: 'just have class days')" % dev,
                  c.get("shown") and c.get("ring") and c.get("days") == str(want.get("days")) and c.get("tiles") == 0, [c, want])
            check("%s: the course card shows even with the old setting off (no switch in Settings any more)" % dev, a.get("offHidden") is True, a.get("offHidden"))
            o = a.get("order") or []
            check("%s: Today, This week and Next test sit above the month, nothing sideways" % dev,
                  len(o) == 4 and all(v is not None for v in o) and max(o[:3]) < o[3] and a.get("scrollX", 1) <= 0 and a.get("outside") == 0,
                  [o, a.get("scrollX"), a.get("outside")])
            p = a.get("pick") or {}
            check("%s: a day tapped in the week is picked in the month and its card says what is on" % dev,
                  p.get("sel") == p.get("want") and p.get("weekSel") and (p.get("entry") or "x") in (p.get("card") or ""), p)
            # a test day (Mon Oct 12), with topics posted for the NEXT one
            b = pg.evaluate(B324C_CAL, ["2026-10-12", None])
            t = b.get("today") or {}
            n = b.get("next") or {}
            check("%s, a test day: the Today card says Test day and names Test #4; Next test is today" % dev,
                  t.get("status") == "Test day" and "Test #4" in (t.get("testItems") or []) and n.get("date") == "2026-10-12" and n.get("days") == "0"
                  and n.get("num") == "Today", [t, n])
            d = b.get("dot") or {}
            check("%s: today's test dot is still the key's amber" % dev,
                  d.get("today") == d.get("key") == "rgb(245, 181, 77)", d)
            # topics posted for Test #5
            c3 = pg.evaluate(B324C_CAL, ["2026-10-13", TOPICS])
            n = c3.get("next") or {}
            nd = c3.get("ntDay") or {}
            want_t = TOPICS["2026-10-19"]["topics"]
            # MOVED IN 327 (b327c): "where it says the date of when the test
            # got posted, don't include that" - no posted date
            check("%s: TEST_TOPICS shows on the Next test card (with no posted date) and on that day in the month" % dev,
                  n.get("topics") == want_t and not n.get("none") and not (n.get("posted") or "")
                  and nd.get("topics") == want_t and nd.get("topicsCls") and not nd.get("none"), [n, nd])
            # a weekend (Sat Oct 10)
            e = pg.evaluate(B324C_CAL, ["2026-10-10", None])
            t = e.get("today") or {}
            wk = e.get("week") or {}
            check("%s, a Saturday: No class, it's the weekend; the week strip looks ahead to the next week" % dev,
                  t.get("status") == "No class" and "weekend" in (t.get("text") or "")
                  and [x["d"] for x in wk.get("days") or []][:1] == ["2026-10-11"] and "Next week" in (wk.get("head") or ""), [t, wk.get("head")])
        except Exception as ex:
            check("%s: the build 324 calendar could be driven at all" % dev, False, str(ex)[:300])
        ctx.close()




# A recap fixture: last week's rows with the weekly blocks build 324 publishes.
# Ada wins from fifth on Friday night (a comeback); the viewer is sixth on
# points and leads every honorable-mention category outside the top 3;
# Ghost is in this device's cached top three but has no row (hid from the
# rankings) and must never be named.
RECAP_FIXTURE_JS = r"""
  const lw = lastWeekKey(), wk = weekKeyNow(), me = publicIdOf();
  const blk = (x, o) => Object.assign({ k: lw, x: x, t: 4, h: 1, d: 2, m: 120, s: 3, b: 1000,
    p: [Math.round(x / 7), Math.round(x / 7), Math.round(x / 7), Math.round(x / 7), Math.round(x / 7), Math.round(x / 7), x - 6 * Math.round(x / 7)] }, o || {});
  const row = (pub, name, x, o, av) => ({ pub, firstName: name, avatarChar: av || 'ninja', week: wk, weekPoints: 5, rawWeekPoints: 5,
    prevWeek: lw, prevWeekPoints: x, pwk: blk(x, o) });
  window.__recapRows = (opts) => {
    opts = opts || {};
    const rows = [
      row('a1', 'Ada', 9000, { p: [500, 500, 500, 500, 500, 3000, 3500] }, 'ghost'),
      row('b2', 'Bo', 8000, { p: [2000, 2000, 2000, 1000, 500, 300, 200] }, 'alien'),
      row('c3', 'Cy', 7000, { p: [1500, 1500, 1500, 1500, 500, 500, 0] }),
      row('d4', 'Di', 6000, { p: [1200, 1200, 1200, 1200, 1000, 200, 0], t: 6, h: 2, d: 3, m: 200, s: 4, b: 5000 }),
      row('e5', 'Ed', 5000, { p: [1000, 1000, 1000, 1000, 500, 500, 0], t: 5, h: 1, d: 2, m: 150, s: 3, b: 4500 }),
      row(me, store.firstName || 'Me', opts.meX || 3000, { t: 30, h: 9, d: 6, m: 900, s: 7, b: 100 })
    ];
    if(opts.noBlocks) rows.forEach(r => { delete r.pwk; });
    return rows;
  };
  window.__recapMine = (x) => { store.weekKey = wk; store.weekPoints = 5; store.prevWeekKey = lw; store.prevWeekPoints = x; };
  try{ const c = JSON.parse(localStorage.getItem('class26e.weektop.v1') || '{}'); c[lw] = [{ pub: 'ghost9', name: 'Ghost', avatar: 'ninja', pts: 99999 }];
       localStorage.setItem('class26e.weektop.v1', JSON.stringify(c)); }catch(e){}
"""


def check_b324w_recap(br):
    """Build 324 (b324w): Nova's weekly recap on Home. "Every Tuesday we need a
    weekly recap from nova instructor on screen ... instead of it being on
    the leaderboard? It will come in on the main menu ... honorable mentions
    after the top 3 ... I can talk about a comeback ... At the end mention how Mr
    nova will see us next week". It appears on the first Tuesday-or-later
    Home of a week and not twice, never on another screen or under a tour;
    the top 3 in order with the comeback told; mentions skip categories
    with no data, never name the top 3, never repeat a category two weeks
    running, never show a zero; nobody hidden from the rankings is named,
    and a viewer who hides sees nobody else; a mention hands nothing over
    (the Sheriff was dropped from this task by the integrator: he went to a
    Virtual Room match against Nova, another builder's); the first week, with no blocks published yet, has the top 3 and no empty
    mention; the row publishes the blocks; build 289's Leaderboard card is
    gone. Fails on ab75270 (none of it exists; the card is still there)."""
    print("\n_b324w. build 324: Nova's weekly recap on Home, honorable mentions")
    ctx, pg = booted(br, 440, 956, seed=USED_ACCOUNT)
    r = pg.evaluate("""async ()=>{ const wait = ms => new Promise(r => setTimeout(r, ms)); const out = {};
      try{
      document.querySelectorAll('#pushing-update,#intro-pop,.nova-talk').forEach(n => n.remove());
      out.fns = typeof buildWeekRecap === 'function' && typeof maybeShowWeekRecap === 'function' && typeof weekRecapLines === 'function';
      out.oldCard = typeof showWeekCongrats === 'function' || typeof maybeShowWeekCongrats === 'function';
      if(!out.fns) return out;
      """ + RECAP_FIXTURE_JS + """
      /* the day: Tuesday to Sunday, never Monday */
      out.days = [12, 13, 14, 18].map(d => weekRecapDayOk(new Date(2026, 9, d)));
      /* the recap, worked out */
      __recapMine(3000);
      const rec = buildWeekRecap(__recapRows());
      out.top = rec.top.map(t => t.name);
      out.story = rec.story;
      out.ments = rec.mentions.map(m => ({ cat: m.cat, name: m.name, v: m.value, me: m.me }));
      out.mentCount = weekRecapMentionCount(lastWeekKey());
      out.place = rec.viewer.place;
      const texts = weekRecapLines(rec).map(l => l.text);
      out.texts = texts;
      /* empty categories are skipped: only tests reported */
      const only = __recapRows().map(r => { r.pwk = { k: r.pwk.k, x: r.pwk.x, t: r.pwk.t, h: null, d: null, m: null, s: null, b: null, p: null }; return r; });
      out.onlyTests = buildWeekRecap(only).mentions.map(m => m.cat);
      /* a zero is never a winner */
      const zero = __recapRows().map(r => { r.pwk = Object.assign({}, r.pwk, { t: 0, h: 0, d: 0, m: 0, s: 0, b: null }); return r; });
      out.zeroMents = buildWeekRecap(zero).mentions.length;
      /* the rotation: twelve weeks of full data, never a category two weeks running, and it moves */
      try{ localStorage.removeItem('class26e.weekrecap.v1'); }catch(e){}
      const weeks = []; { const p = lastWeekKey().split('-').map(Number); for(let i = 0; i < 12; i++){ const d = new Date(p[0], p[1] - 1, p[2] + 7 * i); weeks.push(dayKey(d)); } }
      const listFor = k => __recapRows().map(r => { r.pwk = Object.assign({}, r.pwk, { k }); r.prevWeek = k; return r; });
      const picked = weeks.map(k => weekRecapMentions(listFor(k), [{ pub: 'a1' }, { pub: 'b2' }, { pub: 'c3' }], k).map(m => m.cat));
      out.rotRepeats = picked.slice(1).filter((c, i) => c.some(x => picked[i].indexOf(x) >= 0)).length;
      out.rotDistinct = new Set([].concat(...picked)).size;
      out.rotEmpty = picked.filter(c => !c.length).length;
      /* the first week: nobody has published a block yet */
      const first = buildWeekRecap(__recapRows({ noBlocks: true }));
      out.firstTop = first ? first.top.map(t => t.name) : null;
      out.firstMents = first ? first.mentions.length : -1;
      out.firstStory = first ? first.story.kind : null;
      out.firstTexts = first ? weekRecapLines(first).map(l => l.text) : [];
      /* the row publishes this week's and last week's blocks */
      store.weekStats = null; store.prevWeekStats = null; rollWeek();
      const t0 = (store.weekStats || {}).t; weekStatsAdd('t', 2); weekStatsAddXp(40);
      const lr = buildLeaderboardRow();
      out.row = { wk: lr.wk && lr.wk.k === weekKeyNow(), pwk: lr.pwk && lr.pwk.k === lastWeekKey(), t: lr.wk ? lr.wk.t - (t0 || 0) : null,
                  lazy: ROW_LAZY_FIELDS.indexOf('wk') >= 0 && ROW_LAZY_FIELDS.indexOf('pwk') >= 0 };
      /* the week rolls its counters over and keeps last week's total as b */
      store.weekKey = lastWeekKey(); store.weekPoints = 777; store.weekStats = { k: lastWeekKey(), t: 3, h: 1, d: 1, b: 0, p: [0,0,0,0,0,0,777] };
      rollWeek();
      out.rolled = { prev: (store.prevWeekStats || {}).k === lastWeekKey() && store.prevWeekStats.t === 3, cur: store.weekStats.k === weekKeyNow() && store.weekStats.t === 0, b: store.weekStats.b };
      out.loadDefault = cleanWeekStats(undefined) === null && cleanWeekStats({ k: 'x' }) === null;
      }catch(e){ out.err = String(e && e.stack || e); }
      return out; }""")
    r = r if isinstance(r, dict) else {}
    check("b324w the recap exists", r.get("fns") is True, r.get("err") or r.get("fns"))
    check("b324w build 289's Leaderboard card is gone", r.get("oldCard") is False, r.get("oldCard"))
    if not r.get("fns"):
        ctx.close()
        return
    check("b324w Tuesday to Sunday, never Monday", r.get("days") == [False, True, True, True], r.get("days"))
    check("b324w the top 3 in order, nobody hidden named", r.get("top") == ["Ada", "Bo", "Cy"], r.get("top"))
    st = r.get("story") or {}
    check("b324w the comeback is told: fifth on Friday, first by Sunday",
          st.get("kind") == "comeback" and st.get("place") == 5, st)
    texts = r.get("texts") or []
    joined = " | ".join(texts)
    check("b324w Nova presents third, second, then first",
          len(texts) > 4 and "third" in texts[1] and "Cy" in texts[1] and "second" in texts[2] and "Bo" in texts[2]
          and "Ada" in texts[3] and "comeback" in texts[3] and "fifth" in texts[3] and "9,000" not in texts[1], texts[:4])
    ments = r.get("ments") or []
    check("b324w one or two mentions, none of them the top 3, the viewer named first",
          len(ments) == r.get("mentCount") and all(m["name"] not in ("Ada", "Bo", "Cy") for m in ments)
          and ments and ments[0]["me"], ments)
    check("b324w the mention is said to the viewer, and promises no reward",
          "That’s you" in joined and "Sheriff" not in joined and "unlock" not in joined.lower(), [t for t in texts if "you" in t])
    check("b324w he ends by seeing everyone next week", texts and "next Tuesday" in texts[-1], texts[-1:] if texts else None)
    check("b324w never Ghost (no row: hidden from the rankings)", "Ghost" not in joined, joined[:200])
    check("b324w categories with no data are skipped", set(r.get("onlyTests") or []) <= {"tests"}, r.get("onlyTests"))
    check("b324w a zero is never a mention", r.get("zeroMents") == 0, r.get("zeroMents"))
    check("b324w the mentions rotate: never one category two weeks running, and they move",
          r.get("rotRepeats") == 0 and (r.get("rotDistinct") or 0) >= 4 and r.get("rotEmpty") == 0,
          [r.get("rotRepeats"), r.get("rotDistinct"), r.get("rotEmpty")])
    ft = r.get("firstTexts") or []
    check("b324w the first week: the top 3 from last week's totals, no mentions, no zeros",
          r.get("firstTop") == ["Ada", "Bo", "Cy"] and r.get("firstMents") == 0 and r.get("firstStory") != "comeback"
          and not any(re.search(r"\b0 (XP|tests?|hundos?)\b|nobody|undefined|null|NaN", t) for t in ft),
          [r.get("firstTop"), r.get("firstMents"), r.get("firstStory")])
    check("b324w the row publishes this week's and last week's blocks (lazily)",
          r.get("row") == {"wk": True, "pwk": True, "t": 2, "lazy": True}, r.get("row"))
    check("b324w the week rolls its counters and keeps last week's total",
          (r.get("rolled") or {}).get("prev") and (r.get("rolled") or {}).get("cur") and (r.get("rolled") or {}).get("b") == 777
          and r.get("loadDefault") is True, [r.get("rolled"), r.get("loadDefault")])
    ctx.close()

    # The flow on Home: not under a tour, not on another screen, once a week.
    ctx, pg = booted(br, 440, 956, seed=USED_ACCOUNT)
    r = pg.evaluate("""async ()=>{ const wait = ms => new Promise(r => setTimeout(r, ms)); const out = {};
      try{
      document.querySelectorAll('#pushing-update,#intro-pop,.nova-talk').forEach(n => n.remove());
      if(typeof buildWeekRecap !== 'function') return { none: true };
      """ + RECAP_FIXTURE_JS + """
      window.weekRecapDayOk = () => true;
      store.pendingCharUnlocks = [];
      const locks0 = AVATAR_CHARACTERS.map(c => isLockedCharacter(c.id)).join(',');
      __recapMine(3000);
      leaderboardRows = __recapRows(); leaderboardRowsFromServer = true;
      try{ localStorage.removeItem('class26e.weekrecap.v1'); }catch(e){}
      const up = () => document.querySelector('.nova-talk.is-weekrecap');
      /* another screen: nothing */
      showProfile('profile'); await wait(300); maybeShowWeekRecap(0); await wait(600);
      out.onProfile = !!up();
      /* Home under a tour: it waits */
      const tour = document.createElement('div'); tour.id = 'tour-overlay'; document.body.appendChild(tour);
      showHome(); await wait(4200);
      out.underTour = !!up();
      tour.remove();
      for(let i = 0; i < 40 && !up(); i++) await wait(150);
      const el = up();
      out.shown = !!el;
      if(el){
        out.onHome = !!stage.querySelector('[data-screen="home"]');
        out.marked = (localStorage.getItem('class26e.weekrecap.v1') || '').indexOf(lastWeekKey()) >= 0;
        const said = [];
        for(let k = 0; k < 40; k++){
          const n = el.__nova; if(!n) break;
          if(n.typing){ n.advance(); await wait(80); }
          said[n.index] = (el.querySelector('.nt-text') || {}).textContent || '';
          if(n.index >= n.count - 1) break;
          n.advance(); await wait(700);
        }
        out.said = said;
        out.podium = [...el.querySelectorAll('.wr-col.is-up .wr-name')].map(n => n.textContent);
        out.cards = el.querySelectorAll('.wr-mention.is-in').length;
        out.meCard = !!el.querySelector('.wr-mention.is-me');
        /* a mention is recognition, not an unlock: nothing changes hands */
        out.untouched = AVATAR_CHARACTERS.map(c => isLockedCharacter(c.id)).join(',') === locks0
          && !(store.pendingCharUnlocks || []).length && store.mentionWeeks === undefined;
        out.skip = !!el.querySelector('.nt-skip');
        el.__nova.close('done'); await wait(600);
      }
      out.gone = !up();
      /* not twice */
      showHome(); await wait(4200);
      out.again = !!up();
      /* the Leaderboard never congratulates any more */
      try{ localStorage.removeItem('class26e.weekcongrats.v1'); }catch(e){}
      showRankings('week'); await wait(1800);
      out.lbCard = !!document.querySelector('.week-congrats, .is-weekrecap');
      showHome(); await wait(300);
      /* a viewer who hides from the rankings: the recap without the class */
      document.querySelectorAll('.nova-talk, .rs-spot, .rs-fly, .scene-bridge, .invite-overlay').forEach(n => n.remove()); weekRecapOn = false;
      try{ localStorage.removeItem('class26e.weekrecap.v1'); }catch(e){}
      /* build 326 (b326e): the recap is the day's one moment of his
         (playWeekRecap stamps novaHeard['@last'], and maybeShowWeekRecap
         waits for a day he has not spoken on), so the first recap above
         rightly holds back a second one today. This leg is another week's
         recap for a viewer who hides, so it is another day too. */
      try{ if(store.novaHeard) delete store.novaHeard['@last']; }catch(e){}
      store.leaderboardOptIn = false;
      showHome();
      for(let i = 0; i < 40 && !up(); i++) await wait(150);
      const oo = up();
      out.optShown = !!oo;
      if(oo){
        const lines = weekRecapLines(oo.__recap).map(l => l.text).join(' | ');
        out.optNames = ['Ada', 'Bo', 'Cy', 'Di', 'Ed', 'Ghost'].filter(n => lines.indexOf(n) >= 0);
        out.optPodium = !!oo.querySelector('.wr-podium, .wr-mention');
        out.optSettings = /Show me in the rankings/.test(lines);
        oo.__nova.close('skip');
      }
      }catch(e){ out.err = String(e && e.stack || e); }
      return out; }""")
    r = r if isinstance(r, dict) else {}
    check("b324w not on another screen", r.get("onProfile") is False, r.get("err") or r.get("onProfile"))
    check("b324w not under a tour", r.get("underTour") is False, r.get("underTour"))
    check("b324w on Home once the tour has gone, marked seen", r.get("shown") is True and r.get("onHome") is True and r.get("marked") is True,
          [r.get("shown"), r.get("onHome"), r.get("marked")])
    said = [s for s in (r.get("said") or []) if s]
    check("b324w the podium rose third, second, first, and the mentions came in as cards",
          r.get("podium") and sorted(r.get("podium")) == ["Ada", "Bo", "Cy"] and (r.get("cards") or 0) >= 1 and r.get("meCard") is True,
          [r.get("podium"), r.get("cards"), r.get("meCard")])
    check("b324w the viewer's mention unlocks nothing (the Sheriff is not the recap's)", r.get("untouched") is True, r.get("untouched"))
    check("b324w skippable, and closed", r.get("skip") is True and r.get("gone") is True, [r.get("skip"), r.get("gone")])
    check("b324w not twice in a week", r.get("again") is False, r.get("again"))
    check("b324w nothing on the Leaderboard", r.get("lbCard") is False, r.get("lbCard"))
    check("b324w a viewer who hides sees the recap without anybody else in it",
          r.get("optShown") is True and r.get("optNames") == [] and r.get("optPodium") is False and r.get("optSettings") is True,
          [r.get("optShown"), r.get("optNames"), r.get("optPodium"), r.get("optSettings")])
    ctx.close()




def check_b324t_stats(br):
    """Build 324 (b324t): Profile's Stats tab. "I also attached a study
    hour chart, I really like the looks of it, could we add something
    like that in stats? It'd be yours, you can't see others, but it looks
    sick, better than the one we have I think." The seven bars became a
    dot chart: Mon-Sun of this week (weekKeyNow's week), one column of
    dots a day at a resolution that fits the busier week, a white cap at
    the value, today marked, last week on a switch, a tapped column read
    out exactly, and the light-up fired when the tab is SHOWN, not when
    it is built. "the virtual room section looks funny, improve this":
    three tiles on one row that never wrap or overflow a 320px phone,
    and one plain line instead of three zeros before a first match. And
    At a glance no longer leaves a hole beside Hundos (phone) or at the
    end of its row (tablet). Fails on ab75270 (bars, no switch, no
    Virtual Room section, the holes)."""
    print("\n_b324t. build 324: the study-hour dots, last week, a tapped day, the Virtual Room tiles")
    H = 3600000
    # Whole milliseconds, as a real log holds: 4.4 * H is 15840000.000000002
    # as a float, which the chart echoes back and int() then truncates, so
    # the check failed from Friday on (when that day joins the week).
    this_w = [round(h * H) for h in (2.4, 0.6, 3.1, 1.75, 4.4, 2.9, 1.2)]
    last_w = [round(h * H) for h in (1.1, 2.2, 0, 3.6, 0.9, 0, 5.3)]
    js = """async ([thisW, lastW, vr]) => {
      const wait = ms => new Promise(r => setTimeout(r, ms));
      const out = {};
      try{
      document.querySelectorAll('#pushing-update,#intro-pop').forEach(n => n.remove());
      const now = new Date();
      const ti = (now.getDay() + 6) % 7;
      const mon = new Date(now.getFullYear(), now.getMonth(), now.getDate() - ti);
      const at = i => dayKey(new Date(mon.getFullYear(), mon.getMonth(), mon.getDate() + i));
      store.studyLog = {};
      const thisLogged = thisW.map((v, i) => i <= ti ? v : 0);
      thisLogged.forEach((v, i) => { if(v) store.studyLog[at(i)] = v; });
      lastW.forEach((v, i) => { if(v) store.studyLog[at(i - 7)] = v; });
      store.studyLog[at(-30)] = 2 * 3600000;
      store.vrMatches = vr[0]; store.vrWins = vr[1]; store.vrTop3 = vr[2];
      out.ti = ti; out.thisLogged = thisLogged;
      /* built on the Profile tab: the chart exists, hidden, and has not played */
      showProfile('profile'); await wait(900);
      const ch0 = document.querySelector('.profile-stats-tab .stx-dots');
      const unlit = el => { const d = document.createElement('span'); d.className = 'stx-dot'; el.appendChild(d);
        const c = getComputedStyle(d).backgroundColor; d.remove(); return c; };
      if(ch0){
        const lit = ch0.querySelector('.stx-dot.on:not(.is-cap)');
        out.built = { pre: ch0.classList.contains('is-pre'), played: ch0.dataset.played || null,
          hidden: ch0.closest('.profile-stats-tab').hidden,
          litBg: lit ? getComputedStyle(lit).backgroundColor : null, unlitBg: unlit(lit.parentElement) };
      }
      document.querySelector('.profile-stats-tab-btn').click();
      const ch = document.querySelector('.profile-stats-tab .stx-dots');
      const midLit = ch ? getComputedStyle(ch.querySelector('.stx-dot.on.is-mid:not(.is-cap)')).backgroundColor : null;
      await wait(1700);
      const read = () => ({ big: ch.querySelector('.stx-dots-big').textContent, cap: ch.querySelector('.stx-dots-cap').textContent });
      const cols = () => [...ch.querySelectorAll('.stx-dcol')].map(c => {
        const mids = [...c.querySelectorAll('.stx-dot.is-mid')];
        const capI = mids.findIndex(d => d.classList.contains('is-cap'));
        return { ms: Number(c.dataset.ms), lit: mids.filter(d => d.classList.contains('on')).length,
                 rows: mids.length, capFromBottom: capI < 0 ? 0 : mids.length - capI,
                 caps: c.querySelectorAll('.is-cap').length, today: c.classList.contains('is-today') };
      });
      const lit = ch.querySelector('.stx-dot.on:not(.is-cap)');
      out.shown = { pre: ch.classList.contains('is-pre'), played: ch.dataset.played || null,
        earlyMid: midLit, litBg: getComputedStyle(lit).backgroundColor, unlitBg: unlit(lit.parentElement),
        step: Number(ch.dataset.stepMin), rows: Number(ch.dataset.rows), hours: Number(ch.dataset.hours),
        axis: [...ch.querySelectorAll('.stx-dots-axis span')].map(s => s.textContent),
        cols: cols(), read: read(), card: [...document.querySelectorAll('.profile-stats-tab .stat-card')]
          .filter(c => c.querySelector('.stat-lab').textContent === 'This week').map(c => c.querySelector('.stat-num').textContent)[0],
        weekSum: formatDuration(thisLogged.reduce((a, b) => a + b, 0)) };
      /* a tapped day reads out exactly; tapping it again goes back */
      const tapI = Math.min(ti, 2);
      ch.querySelectorAll('.stx-dcol')[tapI].click(); await wait(250);
      out.tap = { read: read(), want: formatDuration(thisLogged[tapI]),
        picked: ch.querySelectorAll('.stx-dcol.is-picked').length };
      ch.querySelectorAll('.stx-dcol')[tapI].click(); await wait(250);
      out.untap = read();
      /* last week */
      const before = Number(ch.dataset.played);
      ch.querySelector('.stx-dots-switch [data-week="prev"]').click(); await wait(1500);
      out.prev = { cols: cols(), read: read(), played: Number(ch.dataset.played) - before, pre: ch.classList.contains('is-pre'),
        sel: ch.querySelector('[data-week="prev"]').getAttribute('aria-selected'),
        want: formatDuration(lastW.reduce((a, b) => a + b, 0)) };
      ch.querySelectorAll('.stx-dcol')[3].click(); await wait(250);
      out.prevTap = { read: read(), want: formatDuration(lastW[3]) };
      /* the Virtual Room */
      const vrs = document.querySelector('.profile-stats-tab .stx-vr');
      out.vr = vrs ? { cells: [...vrs.querySelectorAll('.stx-vr-cell')].map(c => {
          const r = c.getBoundingClientRect(), l = c.querySelector('.stat-lab');
          return { top: Math.round(r.top), left: r.left, right: r.right, label: l.textContent, num: c.querySelector('.stat-num').textContent,
                   lines: Math.round(l.getBoundingClientRect().height / parseFloat(getComputedStyle(l).lineHeight || 16)) || 1,
                   cut: l.scrollWidth > l.clientWidth + 1 }; }),
        sect: (r => ({ left: r.left, right: r.right }))(vrs.getBoundingClientRect()),
        empty: !!vrs.querySelector('.stx-vr-empty'), text: vrs.textContent } : null;
      /* At a glance: the four under Total XP fill their rows */
      const g = [...document.querySelectorAll('.stx-glance .stat-grid > .stat-card')].map(c => (r => ({ t: Math.round(r.top), l: Math.round(r.left), r: Math.round(r.right) }))(c.getBoundingClientRect()));
      const gg = document.querySelector('.stx-glance .stat-grid').getBoundingClientRect();
      out.glance = { cards: g, gridRight: Math.round(gg.right) };
      /* nothing on the tab wider than the screen */
      out.overflow = document.documentElement.scrollWidth - innerWidth;
      const dr = ch.getBoundingClientRect();
      out.dotsOut = [...ch.querySelectorAll('.stx-dcol-grid, .stx-dcol-lab')].filter(e => { const r = e.getBoundingClientRect(); return r.left < dr.left - .5 || r.right > dr.right + .5; }).length;
      const labs = [...ch.querySelectorAll('.stx-dcol-lab')].map(e => e.getBoundingClientRect());
      out.labTouch = labs.slice(1).filter((r, i) => r.left < labs[i].right + 1).length;
      }catch(e){ out.err = String(e && e.stack || e); }
      return out; }"""

    def expect_lit(ms, step, rows):
        if ms <= 0:
            return 0
        return max(1, min(rows, int(math.floor(ms / (step * 60000) + 0.5))))

    for label, w, h in [PHONE, TABLET, ("320px phone", 320, 568)]:
        ctx, pg = booted(br, w, h, seed=USED_ACCOUNT, touch=True)
        vr = [14, 3, 8]
        r = pg.evaluate(js, [this_w, last_w, vr])
        if r.get("err"):
            check("%s: the Stats run completed" % label, False, r["err"][:300])
            ctx.close()
            continue
        b, s = r.get("built"), r.get("shown") or {}
        ti = r["ti"]
        if label != "320px phone":
            check("%s: built behind another tab the chart waits dim (no light-up until Stats is SHOWN)" % label,
                  bool(b) and b["hidden"] and b["pre"] and not b["played"] and b["litBg"] == b["unlitBg"], b)
            check("%s: shown, it plays once and lands lit (a lit dot is not an unlit one; still dim the instant it is shown)" % label,
                  s.get("played") == "1" and not s.get("pre") and s.get("litBg") != s.get("unlitBg")
                  and s.get("earlyMid") == s.get("unlitBg"), {k: s.get(k) for k in ("played", "pre", "litBg", "unlitBg", "earlyMid")})
        mx = max(max(r["thisLogged"]), max(last_w))
        hours = max(2, int(math.ceil(mx / H - 1e-9)))
        step = next((x for x in (10, 15, 20, 30, 60, 120) if hours * 60 / x <= 16), 120)
        rows = int(math.ceil(hours * 60 / step))
        cols = s.get("cols") or []
        check("%s: seven columns, Monday to Sunday, on a %dh scale at %d min a dot (%d rows), axis 1h..%dh"
              % (label, hours, step, rows, hours),
              len(cols) == 7 and s.get("step") == step and s.get("rows") == rows and s.get("hours") == hours
              and all(c["rows"] == rows for c in cols) and (s.get("axis") or [None])[-1] == "%dh" % hours,
              {k: s.get(k) for k in ("step", "rows", "hours", "axis")})
        want = [expect_lit(v, step, rows) for v in r["thisLogged"]]
        check("%s: the dots lit in each day's middle column are its logged time at that resolution" % label,
              [c["lit"] for c in cols] == want and [c["ms"] for c in cols] == [int(v) for v in r["thisLogged"]],
              {"got": [c["lit"] for c in cols], "want": want})
        check("%s: one white cap per studied day, sitting at the value" % label,
              all((c["caps"] == 1 and c["capFromBottom"] == n) if n else c["caps"] == 0 for c, n in zip(cols, want)),
              [(c["caps"], c["capFromBottom"], n) for c, n in zip(cols, want)])
        check("%s: today, and only today, is marked" % label,
              [i for i, c in enumerate(cols) if c["today"]] == [ti], [c["today"] for c in cols])
        check("%s: the reading is the week's total, the same as the This week card (Monday on)" % label,
              (s.get("read") or {}).get("big") == s.get("weekSum") == s.get("card"),
              (s.get("read"), s.get("weekSum"), s.get("card")))
        t = r.get("tap") or {}
        check("%s: a tapped day shows its exact time and is picked; a second tap goes back to the total" % label,
              t.get("read", {}).get("big") == t.get("want") and t.get("picked") == 1
              and r.get("untap", {}).get("big") == s.get("weekSum"), (t, r.get("untap")))
        p = r.get("prev") or {}
        pw = [expect_lit(v, step, rows) for v in last_w]
        check("%s: Last week draws last week on the same scale, plays again, and marks no today" % label,
              [c["lit"] for c in p.get("cols", [])] == pw and not any(c["today"] for c in p.get("cols", []))
              and p.get("played") == 1 and p.get("sel") == "true" and p.get("read", {}).get("big") == p.get("want"),
              {"lit": [c["lit"] for c in p.get("cols", [])], "want": pw, "played": p.get("played"), "read": p.get("read"), "total": p.get("want")})
        check("%s: and a tapped day of last week reads its own time" % label,
              r.get("prevTap", {}).get("read", {}).get("big") == r.get("prevTap", {}).get("want"), r.get("prevTap"))
        v = r.get("vr") or {}
        cells = v.get("cells") or []
        check("%s: the Virtual Room is three tiles on ONE row, inside the section, each label on one line and whole" % label,
              len(cells) == 3 and len({c["top"] for c in cells}) == 1 and [c["num"] for c in cells] == ["14", "3", "8"]
              and all(c["lines"] == 1 and not c["cut"] for c in cells)
              and all(c["left"] >= v["sect"]["left"] - .5 and c["right"] <= v["sect"]["right"] + .5 for c in cells),
              cells)
        check("%s: nothing on the Stats tab runs off the side, and no dot column or day name leaves its card or touches the next"
              % label, r.get("overflow") == 0 and r.get("dotsOut") == 0 and r.get("labTouch") == 0,
              (r.get("overflow"), r.get("dotsOut"), r.get("labTouch")))
        g = r.get("glance") or {}
        cs = g.get("cards") or []
        # FOUR CARDS since build 325 (Total XP removed - "Remove that."):
        # two even rows on a phone, one full row on a tablet, no hole.
        if len(cs) == 4 and label != "320px phone":
            if w < 640:
                ok = cs[0]["t"] == cs[1]["t"] and cs[2]["t"] == cs[3]["t"] and cs[0]["t"] != cs[2]["t"]
            else:
                ok = len({c["t"] for c in cs}) == 1 and abs(cs[3]["r"] - g["gridRight"]) <= 1
            check("%s: At a glance leaves no hole (two even rows / four fill the tablet row)" % label, ok, g)
        elif label != "320px phone":
            check("%s: At a glance has four cards (no Total XP since 325)" % label, False, g)
        # the empty Virtual Room
        r2 = pg.evaluate("""async () => { store.vrMatches = 0; store.vrWins = 0; store.vrTop3 = 0;
          showProfile('stats'); await new Promise(r => setTimeout(r, 900));
          const v = document.querySelector('.profile-stats-tab .stx-vr');
          return v ? { cells: v.querySelectorAll('.stx-vr-cell, .stat-card').length, empty: !!v.querySelector('.stx-vr-empty'),
                       text: v.textContent, over: document.documentElement.scrollWidth - innerWidth,
                       inside: (o => { const e = v.querySelector('.stx-vr-empty'); if(!e) return false; const r = e.getBoundingClientRect(); return r.left >= o.left - .5 && r.right <= o.right + .5; })(v.getBoundingClientRect()) } : null; }""")
        check("%s: before a first match the section says so in one line, with no zero tiles" % label,
              bool(r2) and r2["cells"] == 0 and r2["empty"] and "No matches yet" in r2["text"] and r2["over"] == 0 and r2["inside"], r2)
        ctx.close()




# Records every Firestore write and every pushToCloud, so a Nova check can
# assert that none of it touches the server.
B324N_REC = """() => {
  window.__fsw = [];
  /* only what happens INSIDE one of Nova's own functions counts - the app
     around him (Home's presence, a launch's republish) is not his */
  window.__novaDepth = 0;
  const rec = (kind, path) => function(){ if(window.__novaDepth > 0) window.__fsw.push(kind + ' ' + path); return Promise.resolve(); };
  ['novaBefriend', 'novaSendDM', 'novaTick', 'novaUserSent', 'openNovaChat', 'openNovaCard', 'novaFriendMoment',
   'novaReplyFor', 'novaRewrite', 'novaArrived'].forEach(n => {
    const f = window[n]; if(typeof f !== 'function') return;
    window[n] = function(){ window.__novaDepth++; try{ return f.apply(this, arguments); } finally { window.__novaDepth--; } };
  });
  const docRef = (path) => ({
    set: rec('set', path), update: rec('update', path), delete: rec('delete', path),
    get: function(){ return Promise.resolve({ exists: false, data: () => ({}), metadata: { fromCache: false } }); },
    collection: (c) => ({ doc: (d) => docRef(path + '/' + c + '/' + d) })
  });
  fbDb = { collection: (c) => ({ doc: (d) => docRef(c + '/' + d), get: () => Promise.resolve({ forEach(){}, docs: [] }) }),
           runTransaction: function(){ window.__fsw.push('transaction'); return Promise.resolve(); },
           batch: function(){ return { set: rec('bset', ''), update: rec('bupdate', ''), delete: rec('bdelete', ''), commit: () => Promise.resolve() }; } };
  window.__push = 0;
  const push = pushToCloud, save = saveStore;
  pushToCloud = function(){ if(window.__novaDepth > 0) window.__push++; };
  saveStore = function(){ if(window.__novaDepth > 0) window.__push++; return save.apply(this, arguments); };
  return true;
}"""


def check_b324n_nova(br):
    """Build 324 (b324n). Madison: "maybe Mr nova is a chat notification and
    will randomly send you messages? ... give him the rank of supernova, and
    when you click on profile it will pop his stats ... make his banner the
    supernova one ... if you get a message from him it'd show up like any
    other message. Anytime someone ranks up, when that entire cutscene is
    over he will send you a dm saying congrats. When Mr nova introduces
    himself, throughout that cutscene you will get the added friends
    notification thing saying y'all are now friends ... He will mention that
    he is available to challenge now ... a message when new updates are
    out ... he will randomly give tips. We don't want him to be annoying ...
    If I message him, he'll say something automated depending on the
    question but he won't be an ai bot. Or maybe you make him unavailable if
    he can't chat so it won't let you message him sometimes?"
    Nova is a local contact: a friend after his introduction (the FRIENDS
    banner partway through it) and, for an account that met him before,
    quietly on its first Home with a hello; his chat is a row on the
    Friends tab with the unread dot and the button's count; his thread is a
    DM; keyword replies; away blocks the composer; his card is Supernova on
    the Supernova banner with lore stats, Message and no Add friend; rank
    congratulations only after the journey ends; a broadcast once, not
    early, not stale; tips rate-limited; the challenge once; never on the
    leaderboard or in friendPublicIds; and none of it writes to Firestore.
    Fails on ab75270."""
    print("\n324n. Nova is a contact: friends, his chat, his card, his messages")
    seed = USED_ACCOUNT.replace('"onboardingComplete":true,', '"onboardingComplete":true,"novaMet":1,"publicId":"PUBMADISON01",', 1)
    ctx, pg = booted(br, 440, 956, seed=seed)
    pg.evaluate(B324N_REC)
    has = pg.evaluate("() => typeof novaIsFriend === 'function' && typeof novaSendDM === 'function' && typeof novaContactInfo === 'function'")
    check("Nova's contact API exists (novaContactInfo, novaSendDM)", has)
    if not has:
        ctx.close()
        return
    info = pg.evaluate("() => novaContactInfo()")
    check("novaContactInfo() names him, his character, Supernova and the Supernova banner",
          info.get("name") == "Nova" and info.get("rank") == "titan" and info.get("banner") == "titan_rank" and info.get("character"), info)

    # An account that met him before this build: friends quietly on its first Home, with a hello.
    r = pg.evaluate("""async () => { const wait = ms => new Promise(r => setTimeout(r, ms));
      novaAwayForce = false;
      const before = novaIsFriend();
      showHome(); await wait(4600);
      const t = novaThread();
      return { before, after: novaIsFriend(), thread: t.map(m => m.key + ':' + m.text), unread: novaUnread(),
               dot: (document.getElementById('chatdock-dot') || {}).textContent, dotHidden: (document.getElementById('chatdock-dot') || {}).hidden,
               preview: [...document.querySelectorAll('.vroom-chat-alert.is-ping')].map(e => e.textContent).join('|'),
               store: JSON.stringify(store).indexOf('Hello again') >= 0 }; }""")
    hello = (r.get("thread") or [""])[0]
    check("an existing account is not a friend before this build's first Home, and is after it", not r.get("before") and r.get("after"), r)
    check("...quietly: his hello is an unread DM and the chat button counts it, with no banner over the screen",
          hello.startswith("nova:Hello again, Madison") and r.get("unread") and not r.get("dotHidden") and int(r.get("dot") or 0) >= 1
          and "Nova" not in (r.get("preview") or ""), {k: r.get(k) for k in ("thread", "unread", "dot", "preview")})
    # His row on the Friends tab, unread, and the thread.
    r = pg.evaluate("""async () => { const wait = ms => new Promise(r => setTimeout(r, ms));
      chatDockTab = 'friends'; openChatDock(); await wait(400);
      const row = document.querySelector('.chatdock-chatrow.is-nova');
      const out = { row: !!row, unread: !!(row && row.classList.contains('is-unread')),
        name: row && row.querySelector('.chatdock-chatrow-name').textContent,
        sub: row && row.querySelector('.chatdock-chatrow-sub').textContent,
        tabCount: (document.getElementById('chatdock-friendscount') || {}).textContent,
        face: !!(row && row.querySelector('.nova-svg')) };
      row.querySelector('.chatdock-chatrow-open').click(); await wait(700);
      out.open = chatRoomCode;
      out.msgs = [...document.querySelectorAll('#chatdock .vroom-chat-msg')].map(e => e.textContent);
      out.head = (document.querySelector('#chatdock .nova-head') || {}).textContent;
      out.unreadAfter = novaUnread();
      out.byTab = chatUnreadByTab();
      out.plus = !!document.querySelector('#chatdock .vroom-chat-plusbtn');
      out.friends = friendPublicIds();
      return out; }""")
    check("his chat is a row on the Friends tab, with his face, unread, counted on the tab",
          r.get("row") and r.get("face") and r.get("unread") and r.get("name") == "Nova" and "Hello again" in (r.get("sub") or "") and r.get("tabCount") == "1",
          {k: r.get(k) for k in ("row", "face", "unread", "name", "sub", "tabCount")})
    check("opening it shows the thread like any DM and reads it", r.get("open") == "DM-NOVA" and any("Hello again" in m for m in r.get("msgs") or [])
          and "Nova" in (r.get("head") or "") and not r.get("unreadAfter") and (r.get("byTab") or {}).get("friends") == 0 and not r.get("plus"),
          {k: r.get(k) for k in ("open", "msgs", "head", "unreadAfter", "byTab", "plus")})
    check("he is not one of friendPublicIds() (no inbox, invite or friend count is his)", "nova" not in (r.get("friends") or []), r.get("friends"))

    # Keyword replies, typed into the real composer.
    r = pg.evaluate("""async () => { const wait = ms => new Promise(r => setTimeout(r, ms));
      const say = async (txt) => { const inp = document.querySelector('#chatdock .vroom-chat-input'); inp.value = txt;
        document.querySelector('#chatdock .vroom-chat-send').click(); await wait(3600);
        const t = novaThread(); return t[t.length - 1]; };
      const a = await say("what's on the next test?");
      const b = await say('how do I rank up');
      const c = await say('want to race in a virtual room');
      const d = await say('do you like pizza');
      const shown = [...document.querySelectorAll('#chatdock .vroom-chat-msg')].map(e => e.textContent);
      return { a: a.key + ':' + a.text, b: b.key + ':' + b.text, c: c.key + ':' + c.text, d: d.key + ':' + d.text,
               mine: novaThread().filter(m => m.key !== 'nova').map(m => m.text), shown: shown.slice(-2) }; }""")
    check("keyword replies: the next test points to the Calendar tab", r.get("a", "").startswith("nova:") and "Calendar" in r.get("a", ""), r.get("a"))
    check("keyword replies: ranks, and the Virtual Room challenge with the Sheriff", "Bronze" in r.get("b", "") and "Supernova" in r.get("b", "")
          and "Virtual Room" in r.get("c", "") and "Sheriff" in r.get("c", ""), [r.get("b"), r.get("c")])
    check("anything else gets a polite can't-chat line, and the conversation is on screen", "can’t" in r.get("d", "") and len(r.get("mine") or []) == 4
          and any("pizza" in x for x in r.get("shown") or []) or any("can’t" in x for x in r.get("shown") or []), r)

    # Away: the composer says so and does not send.
    r = pg.evaluate("""async () => { const wait = ms => new Promise(r => setTimeout(r, ms));
      novaAwayForce = true; await wait(1300);
      const inp = document.querySelector('#chatdock .vroom-chat-input');
      const n0 = novaThread().length;
      inp.value = 'hello?'; document.querySelector('#chatdock .vroom-chat-send').click();
      inp.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true })); await wait(2600);
      const out = { disabled: inp.disabled, ph: inp.placeholder, status: (document.querySelector('.nova-head-status') || {}).textContent,
                    sent: novaThread().length - n0, api: novaUserSent({ id: 'x', text: 'hi' }) };
      novaAwayForce = false; await wait(1300);
      out.back = !document.querySelector('#chatdock .vroom-chat-input').disabled;
      return out; }""")
    # MOVED IN 326 (b326e): in-world - out of range, back in range in N min
    check("away: the composer is off and says he is out of range, and nothing is sent", r.get("disabled") and "out of range" in (r.get("ph") or "").lower()
          and "back in range" in (r.get("status") or "") and r.get("sent") == 0 and r.get("api") is False, r)
    check("available again: the composer is back", r.get("back"), r)

    # His card.
    r = pg.evaluate("""async () => { const wait = ms => new Promise(r => setTimeout(r, ms));
      document.querySelector('#chatdock .nova-head').click(); await wait(500);
      const c = document.querySelector('.person-card.is-nova');
      if(!c) return { card: false };
      const out = { card: true, name: c.querySelector('.person-sheet-name').textContent,
        rank: (c.querySelector('.person-card-rank') || {}).textContent, banner: !!c.querySelector('.person-card-cover .bnr-titan_rank'),
        cells: [...c.querySelectorAll('.person-card-cell')].map(e => e.textContent), text: c.innerText,
        acts: [...c.querySelectorAll('button')].map(b => b.textContent), face: !!c.querySelector('.person-card-art .nova-svg') };
      [...c.querySelectorAll('button')].find(b => b.textContent === 'Message').click(); await wait(400);
      out.after = chatRoomCode; out.cardGone = !document.querySelector('.person-card.is-nova');
      return out; }""")
    check("his card: Nova, Supernova, on the Supernova banner, with his face", r.get("card") and r.get("name") == "Nova" and r.get("rank") == "Supernova"
          and r.get("banner") and r.get("face"), {k: r.get(k) for k in ("card", "name", "rank", "banner", "face")})
    check("...stats that fit the lore (badges recovered, flares lit, crew found), Message and no Add friend",
          any("Badges recovered" in x for x in r.get("cells") or []) and any("Crew found" in x for x in r.get("cells") or [])
          and "Message" in (r.get("acts") or []) and not any("friend" in a.lower() for a in r.get("acts") or [])
          and r.get("after") == "DM-NOVA" and r.get("cardGone"), {k: r.get(k) for k in ("cells", "acts", "after")})

    # Never on the leaderboard.
    r = pg.evaluate("""async () => { const wait = ms => new Promise(r => setTimeout(r, ms));
      closeChatDock(); try{ showRankings(); }catch(e){} await wait(800);
      return { rows: [...document.querySelectorAll('#stage .rank-row')].map(e => e.textContent).join('|'),
               lb: (leaderboardRows || []).some(e => e && (e.pub === 'nova' || e.firstName === 'Nova')) }; }""")
    check("he never appears on the leaderboard", "Nova" not in (r.get("rows") or "") and not r.get("lb"), (r.get("rows") or "")[:120])

    # Any later message of his arrives like a classmate's: a preview banner that opens his chat.
    r2 = pg.evaluate("""async () => { const wait = ms => new Promise(r => setTimeout(r, ms));
      /* his chat is still the open one (the dock is shut), so it is the
         panel's own announcement - and from the list, the ping's */
      novaSendDM('Testing, testing.', { kind: 'test' }); await wait(500);
      let b = document.querySelector('.vroom-chat-alert');
      const out0 = b ? b.textContent : null;
      if(b) b.click(); await wait(500);
      const open0 = chatRoomCode, dock0 = chatDockOpen;
      closeChatRoom(); closeChatDock(); await wait(300);
      novaSendDM('Testing again.', { kind: 'test' }); await wait(500);
      b = document.querySelector('.vroom-chat-alert.is-ping');
      const out = { text: b ? b.textContent : null };
      if(b) b.click(); await wait(600);
      out.open = chatRoomCode; out.dock = chatDockOpen; out.text0 = out0; out.open0 = open0; out.dock0 = dock0;
      closeChatRoom(); closeChatDock(); await wait(300);
      return out; }""")
    check("a message from him arrives as a preview banner like any DM, and a tap opens his chat (his chat open or not)",
          "Nova" in (r2.get("text") or "") and "Testing again" in (r2.get("text") or "") and r2.get("open") == "DM-NOVA" and r2.get("dock")
          and "Nova" in (r2.get("text0") or "") and r2.get("open0") == "DM-NOVA" and r2.get("dock0"), r2)
    check("his messages live on the device, not on the synced store", not r.get("store"))

    # Broadcasts: not before their time, once, and never stale.
    # MOVED IN 326 (b326e): he speaks on his own only on Home with nothing
    # owed - the fixture's rank-up still owed (Gold from the old ladder) is
    # shown first, and its reaction counted as said, so only the broadcast
    # is being asked about.
    r = pg.evaluate("""async () => { const wait = ms => new Promise(r => setTimeout(r, ms));
      store.rankUpShown = rankUpHeldIdxReal() + 1; novaHeardMap()['@rank'] = store.rankUpShown; novaSessionAt = 0;
      /* ...nor under another banner: the save-code ask has had its turn */
      try{ localStorage.setItem(SAVE_CODE_ASKED_KEY, '9'); }catch(e){} document.querySelectorAll('.daily-alert').forEach(e => e.remove());
      showHome(); await wait(600);
      const fmt = d => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0')
        + 'T' + String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
      const count = id => novaThread().filter(m => m.text === 'BCAST ' + id).length;
      /* in the first minute and a half of the friendship he says nothing more */
      NOVA_BROADCASTS.push({ id: 'chk-settle', at: fmt(new Date(Date.now() - 3600e3)), text: 'BCAST chk-settle' });
      let s0 = novaState(); s0.since = Date.now() - 30e3; novaSave(s0);
      novaTick(); await wait(100);
      const settle = count('chk-settle');
      s0 = novaState(); s0.since = Date.now() - 3600e3; novaSave(s0);
      NOVA_BROADCASTS.push({ id: 'chk-future', at: fmt(new Date(Date.now() + 3600e3)), text: 'BCAST chk-future' });
      NOVA_BROADCASTS.push({ id: 'chk-old', at: fmt(new Date(Date.now() - 9 * 86400e3)), text: 'BCAST chk-old' });
      /* (326: the settle probe is done with - one broadcast a session, oldest
         first, so it would otherwise be the one that goes) */
      NOVA_BROADCASTS.splice(NOVA_BROADCASTS.findIndex(b => b.id === 'chk-settle'), 1);
      novaTick(); await wait(100);
      const early = count('chk-future');
      NOVA_BROADCASTS.push({ id: 'chk-now', at: fmt(new Date(Date.now() - 3600e3)), text: 'BCAST chk-now' });
      novaTick(); await wait(100); novaTick(); await wait(100); novaTick();
      /* and a new session does not bring it again */
      document.querySelectorAll('.vroom-chat-alert').forEach(e => e.remove()); novaSessionAt = 0;
      novaTick(); await wait(100);
      return { settle, early, now: count('chk-now'), old: count('chk-old'), seeded: NOVA_BROADCASTS[0].id,
               seededText: NOVA_BROADCASTS[0].text }; }""")
    check("a broadcast is not delivered before its time, nor when it is over a week old, nor in the hello's first minute and a half",
          r.get("early") == 0 and r.get("old") == 0 and r.get("settle") == 0, r)
    check("a broadcast that is due is delivered once, not twice", r.get("now") == 1, r)
    check("the seeded broadcast says he can be messaged now", "message me" in (r.get("seededText") or ""), r.get("seededText"))

    # The challenge; then tips, rate-limited; never in a test.
    # MOVED IN 326 (b326e): "ensure you get like a challenge to play him once
    # a week ... Let's not make it where they double up though or become
    # spam whatsoever." The challenge is the week's now (once a week, not
    # once ever), and everything he says on his own goes through one
    # scheduler: one a day on any device of the account (store.novaHeard
    # ["@last"]), never two in a session, a quiet day after this build first
    # runs (["@base"]). check-b326-e holds the rest.
    r = pg.evaluate("""async () => { const wait = ms => new Promise(r => setTimeout(r, ms));
      const D = 86400e3, now = Date.now();
      const k = dayKey(new Date()); store.studyLog = Object.assign({}, store.studyLog, { [k]: 600000 });
      let s = novaState(); s.since = now - 3 * D; s.spontAt = now - 3 * D; novaSave(s);
      const h = novaHeardMap(); h['@base'] = now - 3 * D; h['@last'] = now - 25 * 3600e3; delete h['wk:' + weekKeyNow()];
      novaSessionAt = 0; showHome(); await wait(600);
      document.querySelectorAll('.vroom-chat-alert, .daily-alert').forEach(e => e.remove());
      const kinds = () => novaThread().filter(m => m.kind === 'challenge' || m.kind === 'tip').map(m => m.kind);
      novaTick(); await wait(50);
      const c1 = kinds();
      const chal = (novaThread().filter(m => m.kind === 'challenge')[0] || {}).text;
      document.querySelectorAll('#nova-challenge').forEach(b => b.remove());
      /* a new session the same day: nothing (one a day) */
      novaSessionAt = 0; novaTick(); await wait(50);
      const c2 = kinds();
      /* a day on, in a test: nothing */
      h['@last'] = now - 25 * 3600e3; novaSessionAt = 0;
      testInProgress = true; novaTick(); await wait(50); testInProgress = false;
      const inTest = kinds();
      /* out of the test: not the week's challenge again, a tip */
      novaTick(); await wait(50);
      const c3 = kinds();
      h['@last'] = now - 25 * 3600e3; novaSessionAt = 0;
      novaTick(); await wait(50);
      const c4 = kinds();
      const tip = (novaThread().filter(m => m.kind === 'tip')[0] || {}).text;
      return { c1, c2, inTest, c3, c4, chal, tip, pool: NOVA_TIPS.length }; }""")
    check("the week's challenge message comes once, and says Virtual Room and the Sheriff", r.get("c1") == ["challenge"] and r.get("c2") == ["challenge"]
          and "Virtual Room" in (r.get("chal") or "") and "Sheriff" in (r.get("chal") or ""), r)
    check("a tip waits out a day and a test, then comes once, and not again within its three days",
          r.get("inTest") == ["challenge"] and r.get("c3") == ["challenge", "tip"] and r.get("c4") == ["challenge", "tip"]
          and (r.get("tip") or "").startswith("Tip:") and r.get("pool", 0) >= 8, r)

    # Rank-up congratulations: only once the whole journey has ended.
    # MOVED IN 326 (b326e): "only make his messages appear or get to you
    # when you are out of the profile tab ... maybe when you finally get
    # back to the main menu?" - the journey ends on Profile, and he waits
    # for Home.
    r = pg.evaluate("""async () => { const wait = ms => new Promise(r => setTimeout(r, ms));
      showProfile('profile'); await wait(400);
      const h = novaHeardMap(); h['@last'] = Date.now() - 25 * 3600e3; h['@rank'] = 2; novaSessionAt = 0;
      store.rankUpShown = 2;
      const congrats = () => novaThread().filter(m => m.kind === 'rank').map(m => m.text);
      const scene = { toIdx: 2 };
      rankUpScene = scene;
      store.rankUpShown = 3;
      novaTick(); await wait(100);
      const during = congrats().length;
      rankUpSceneEnd(scene, true);
      await wait(800);
      const justAfter = congrats().length;
      await wait(3200);
      const onProfile = congrats().length;
      showHome(); await wait(4400);
      return { during, justAfter, onProfile, after: congrats() }; }""")
    check("no congratulations while the rank-up journey is still on, nor on Profile after it", r.get("during") == 0 and r.get("justAfter") == 0 and r.get("onProfile") == 0, r)
    check("back on Home, he congratulates you on that rank (Gold)", len(r.get("after") or []) == 1 and "Gold" in (r.get("after") or [""])[0], r)

    w = pg.evaluate("() => ({ w: window.__fsw.slice(), push: window.__push })")
    check("none of it wrote to Firestore, saved the store or pushed the progress document", not w.get("w") and not w.get("push"), w)
    ctx.close()

    # A new account: the friend notification arrives partway through his introduction.
    ctx, pg = booted(br, 440, 956, seed=seed)
    pg.evaluate(B324N_REC)
    r = pg.evaluate("""async () => { const wait = ms => new Promise(r => setTimeout(r, ms));
      localStorage.removeItem('class26e.nova');
      const at = novaIntroLines({}).findIndex(l => l.friend);
      const total = novaIntroLines({}).length;
      playNovaIntro(() => {});
      for(let i = 0; i < 40 && !document.getElementById('nova-intro'); i++) await wait(100);
      const el = document.getElementById('nova-intro'); const nv = el.__nova;
      await wait(500);
      let before = null;
      for(let i = 0; i < 200 && nv.index < at; i++){ if(nv.index === at - 1 && before === null) before = novaIsFriend(); el.querySelector('.nt-stage').click(); await wait(60); }
      await wait(700);
      const note = document.querySelector('.nova-friend-note');
      const r = note ? note.getBoundingClientRect() : null;
      const top = el.querySelector('.nt-top').getBoundingClientRect();
      const out = { at, total, before, idx: nv.index, note: note ? note.textContent : null,
        visible: !!(note && note.classList.contains('show') && r.height > 20), clearOfTop: !!(r && r.top >= top.bottom - 1),
        friend: novaIsFriend(), hello: (novaThread()[0] || {}).text,
        dot: (document.getElementById('chatdock-dot') || {}).textContent,
        line: el.querySelector('.nt-text').textContent };
      nv.skip(); await wait(200);
      const go = el.querySelector('.nt-go'); if(go) go.click(); await wait(900);
      out.after = !!document.getElementById('nova-intro');
      out.noteGone = !document.querySelector('.nova-friend-note.show');
      out.once = novaThread().filter(m => m.kind === 'hello').length;
      return out; }""")
    check("his introduction has a line that makes you friends, partway through (not the first or last)",
          r.get("at", -1) > 1 and r.get("at", 0) < r.get("total", 0) - 1, r)
    check("...not friends before it; on it the FRIENDS banner says 'You and Nova are now friends', clear of his top row",
          r.get("before") is False and r.get("friend") and "You and Nova are now friends" in (r.get("note") or "") and r.get("visible") and r.get("clearOfTop"),
          {k: r.get(k) for k in ("before", "friend", "note", "visible", "clearOfTop", "line")})
    check("...and his hello is waiting in your chats, once", "friends now" in (r.get("hello") or "") and r.get("dot") == "1" and r.get("once") == 1 and r.get("noteGone"),
          {k: r.get(k) for k in ("hello", "dot", "once", "noteGone")})
    w = pg.evaluate("() => ({ w: window.__fsw.slice(), push: window.__push })")
    check("the introduction's friendship wrote nothing to Firestore", not w.get("w") and not w.get("push"), w)
    ctx.close()


def check_b324n2_friends(br):
    """Build 324 (b324n2). Madison: "Nova can appear in the profiles friends
    box, and in manage but the option to remove him won't be there."
    Display only: Profile's Friends box draws him (online-first order, he is
    on while available) with Available/Away, counts him in "N friends" and
    "and N more"; Manage friends draws him as a row with no Remove (no
    button at all) and counts him online while available; a tap opens his
    card; friendPublicIds(), Koi Pond and Firestore never see him.
    Fails on c6a50b9."""
    print("\n324n2. Nova on Profile's Friends box and Manage friends, display only")
    seed = USED_ACCOUNT.replace('"onboardingComplete":true,', '"onboardingComplete":true,"novaMet":1,"publicId":"PUBMADISON01",', 1)
    ctx, pg = booted(br, 440, 956, seed=seed)
    pg.evaluate(B324N_REC)
    ok = pg.evaluate("() => typeof novaManageRow === 'function' && typeof shownFriendsCount === 'function'")
    check("Nova has a row for the friends lists", ok)
    if not ok:
        ctx.close()
        return
    r = pg.evaluate("""async () => { const wait = ms => new Promise(r => setTimeout(r, ms));
      novaAwayForce = false;
      ['novaManageRow', 'shownFriendsCount', 'novaFriendEntry'].forEach(n => { const f = window[n];
        window[n] = function(){ window.__novaDepth++; try{ return f.apply(this, arguments); } finally { window.__novaDepth--; } }; });
      novaBefriend({ quiet: true });
      const now = Date.now();
      const mk = (pub, name, on) => ({ pub, firstName: name, avatarChar: 'robot', level: 30, badges: 4, seenAt: on ? now : now - 864e5, lastModified: 0 });
      leaderboardRows = [mk('pubann000001', 'Ann', true), mk('pubzed000001', 'Zed', true), mk('pubbob000001', 'Bob', false),
                         mk('pubcat000001', 'Cat', false), mk('pubdan000001', 'Dan', false)];
      presenceMap = null;
      store.friendsIn = leaderboardRows.map(e => e.pub);
      const koi0 = BANNERS.find(b => b.id === 'tests500').have();
      /* MOVED IN 327z12 round 2: the Profile Friends box is gone; the count
         is the chat Friends tab's bar */
      const read = async () => { chatDockTab = 'friends'; openChatDock(); await wait(400);
        const info = ((document.querySelector('.chatdock-panel .chatdock-friendsbar-info') || {}).textContent || '').trim();
        closeChatDock(); await wait(300); return { info }; };
      const avail = await read();
      novaAwayForce = true; const away = await read();
      novaAwayForce = false;
      showFriends(); await wait(600);
      const nrow = document.querySelector('.friend-sect .friend-row.is-nova');
      const manage = { has: !!nrow, buttons: nrow ? nrow.querySelectorAll('button').length : -1, text: nrow ? nrow.textContent : '',
        order: [...document.querySelectorAll('.friend-sect .friend-row')].map(r => r.querySelector('.friend-row-name').textContent),
        removes: [...document.querySelectorAll('.friend-sect .friend-row button')].filter(b => b.textContent === 'Remove').length,
        head: [...document.querySelectorAll('.friend-sect .sect-label')].map(e => e.textContent).find(t => /Your friends/.test(t)) };
      nrow.click(); await wait(500);
      manage.card = !!document.querySelector('.person-card.is-nova');
      document.querySelectorAll('.invite-overlay').forEach(o => o.remove());
      return { avail, away, manage, ids: friendPublicIds(), koi0, koi: BANNERS.find(b => b.id === 'tests500').have(),
               w: window.__fsw.slice(), push: window.__push }; }""")
    av, aw, mg = r.get("avail") or {}, r.get("away") or {}, r.get("manage") or {}
    # MOVED IN 327z12 round 2: no Friends box on Profile - the chat's Friends bar counts him
    check("the chat's Friends bar counts him: '6 friends', 3 online while he is available",
          (av.get("info") or "").startswith("6 friends") and "3 online" in (av.get("info") or ""), av)
    check("away, he is not counted online (2 online)", (aw.get("info") or "").startswith("6 friends") and "2 online" in (aw.get("info") or ""), aw)
    check("Manage friends lists Nova with his rank and no Remove (no button at all), the others keep theirs",
          mg.get("has") and mg.get("buttons") == 0 and "Supernova" in (mg.get("text") or "") and "Available" in (mg.get("text") or "")
          and mg.get("removes") == 5 and (mg.get("order") or [])[:3] == ["Ann", "Nova", "Zed"], mg)
    check("...counts him online while he is available, and a tap opens his card", "3 online" in (mg.get("head") or "") and mg.get("card"), mg.get("head"))
    check("display only: not in friendPublicIds(), not counted for Koi Pond", "nova" not in (r.get("ids") or []) and len(r.get("ids") or []) == 5
          and r.get("koi") == r.get("koi0") and r.get("koi", 9) <= 5, {k: r.get(k) for k in ("ids", "koi0", "koi")})
    check("...and nothing of his wrote to Firestore or the store", not r.get("w") and not r.get("push"), {k: r.get(k) for k in ("w", "push")})
    ctx.close()


def check_b324q_penal(br):
    """Build 324: "The penal code slide version will change. It's now going
    to be slides 124-256 ... Ensure each question is correctly there. We
    can't afford any mishaps again." The short version is exactly the 116
    questions on slides 124-256 (PENAL_SLIDES_SRCS, typed from the deck by
    TEXT): every repeat has its own version-only copy at the END of the
    bank, identical to the question it repeats; nothing that was in the
    bank moves (ab75270 is loaded beside this build and its KEYS are a
    byte-identical prefix, and the next 400 daily questions are the same);
    no repeat is ever a daily question; the whole unit is still the study
    guide's 340; the two questions the deck numbers wrongly are in by their
    text; the pop-up, the card and a one-time note under a NEW key all say
    124-256 and count 116. Fails on ab75270 (slides 55-124, 59 questions,
    no copies 351-357, the note keyed penal55124)."""
    import subprocess as _sp
    print("\n324q. Penal Code: the short version is slides 124-256")
    Q = """() => { const pen = QUESTIONS.map((q, i) => i).filter(i => (QUESTIONS[i].topic || '').trim() === 'Penal Code');
      const days = []; for(let d = 0; d < 400; d++){ const k = new Date(2026, 9, 12 + d);
        days.push(dailyQuestionIndexFor(k.getFullYear() + '-' + String(k.getMonth() + 1).padStart(2, '0') + '-' + String(k.getDate()).padStart(2, '0'))); }
      return { keys: KEYS.slice(), n: QUESTIONS.length,
        version: pen.filter(i => inChosenVersion(i, { 'Penal Code': 'test' })).map(i => Number(QUESTIONS[i].src)).sort((a, b) => a - b),
        testSrcs: (typeof PENAL_TEST_SRCS !== 'undefined' ? PENAL_TEST_SRCS.slice() : []).sort((a, b) => a - b),
        whole: pen.filter(i => inWholeUnit(QUESTIONS[i])).map(i => Number(QUESTIONS[i].src)).sort((a, b) => a - b),
        unitSize: unitQuestionCount('Penal Code'),
        bank: pen.map(i => ({ i, src: QUESTIONS[i].src, repeatOf: QUESTIONS[i].repeatOf, vo: QUESTIONS[i].versionOnly === true,
          q: QUESTIONS[i].q, ref: QUESTIONS[i].ref, choices: QUESTIONS[i].choices, answer: QUESTIONS[i].answer })),
        keysUnique: new Set(pen.map(i => KEYS[i])).size === pen.length,
        daily: days.map(i => KEYS[i]), dailyRepeat: days.some(i => QUESTIONS[i] && QUESTIONS[i].repeatOf != null),
        noteKey: typeof penalVersionNoteKey === 'function' ? penalVersionNoteKey() : (typeof PENAL_VERSION_NOTE_KEY !== 'undefined' ? PENAL_VERSION_NOTE_KEY : null),
        live256: typeof penal256Live === 'function' && penal256Live(),
        label: UNIT_TEST_VERSIONS['Penal Code'].label, tag: UNIT_TEST_VERSIONS['Penal Code'].tag }; }"""
    ctx, pg = booted(br, 440, 956, seed=USED_ACCOUNT, init=PIN_BEFORE_PENAL_256)  # 327: before the 256-578 switch
    r = pg.evaluate(Q)
    want = PENAL_SLIDES_SRCS
    check("the slides 124-256 version is exactly the deck's 116 (109 different, seven twice)",
          r["version"] == want and len(want) == 116 and len(set(want) - set(PENAL_REPEATS)) == 109,
          [len(r["version"]), sorted(set(want) ^ set(r["version"]))[:12]])
    check("PENAL_TEST_SRCS is that list, and nothing else", r["testSrcs"] == want, len(r["testSrcs"]))
    by = {}
    for b in r["bank"]:
        by.setdefault(b["src"], []).append(b)
    def same(a, b): return all(a[k] == b[k] for k in ("q", "ref", "choices", "answer"))
    copies = [(c, o, by.get(c), by.get(o)) for c, o in sorted(PENAL_REPEATS.items())]
    check("every repeat has its own version-only copy (351-357), word for word the question it repeats",
          all(cb and ob and len(cb) == 1 and cb[0]["repeatOf"] == o and cb[0]["vo"] and not ob[0]["vo"] and same(cb[0], ob[0])
              for c, o, cb, ob in copies),
          [(c, o, bool(cb), cb and cb[0]["repeatOf"]) for c, o, cb, ob in copies])
    # BUILD 325 appends the slides 256-578 version's own (358-364) after
    # these: every version-only question is still at the end, in src order.
    reps = sorted(b["i"] for b in r["bank"] if b["vo"])
    tail = [b["src"] for b in sorted(r["bank"], key=lambda b: b["i"])][-len(reps):] if reps else []
    check("and every copy sits at the end of the bank (no question's index moves), the 351-357 ones after the older copies",
          reps == list(range(r["n"] - len(reps), r["n"]))
          and tail[-14:] == sorted(PENAL_REPEATS) + list(range(358, 365)), [reps[-9:], tail[-16:]])
    check("the 55-124 copies (347-350) stay in the bank, version-only, out of this version, so their history survives",
          all(by.get(c) and by[c][0]["vo"] and by[c][0]["repeatOf"] == o and c not in r["version"] for c, o in PENAL_OLD_REPEATS.items()),
          [(c, bool(by.get(c))) for c in PENAL_OLD_REPEATS])
    guide = [n for n in range(1, 347) if n not in (122, 137, 148, 237, 256, 258)]
    check("the whole Penal Code unit is still the study guide's 340, with no copy in it",
          r["whole"] == guide and r["unitSize"] == 340, (len(r["whole"]), r["unitSize"]))
    check("every Penal Code question has its own key", r["keysUnique"], r["keysUnique"])
    check("no repeat is ever a daily question (the next 400 days)", not r["dailyRepeat"], r["dailyRepeat"])
    # The two the deck numbers wrongly: slide 148 prints #42 as "60.", slide
    # 156 prints #124 as "125." - in by their TEXT (the build 318 lesson).
    check("by text, not number: #42 is in twice (slide 148 prints it \"60.\"), #124 is in (slide 156 prints it \"125.\"), and #60 is not",
          r["version"].count(42) == 1 and 352 in r["version"] and 124 in r["version"] and 60 not in r["version"] and 125 in r["version"],
          [42 in r["version"], 352 in r["version"], 124 in r["version"], 60 in r["version"]])
    check("the version is named for its slides: label and card line say 124\u2013256",
          "124\u2013256" in r["label"] and "124\u2013256" in r["tag"], [r["label"], r["tag"]])
    check("the one-time note has a NEW key, so a device that saw the 55-124 one is told again",
          r["noteKey"] == ("class26e.penal256578.seen" if r["live256"] else "class26e.penal124256.seen"), r["noteKey"])
    # the pop-up's count, and the note on a device that has seen the 55-124 one
    pop = pg.evaluate("""async () => { const wait = ms => new Promise(r => setTimeout(r, ms));
      store.seenUnitSelectTour = true; cfg.mode = 'drill'; cfg.units = []; cfg.versions = {}; showSetup(); await wait(600);
      let opts = []; askUnitVersion('Penal Code', () => {}); await wait(300);
      opts = [...document.querySelectorAll('#unitver .unitver-opt')].map(b => b.textContent);
      document.querySelector('#unitver .unitver-cancel')?.click(); await wait(300);
      try{ localStorage.removeItem('class26e.penal124256.seen'); localStorage.setItem('class26e.penal55124.seen', '1'); }catch(e){}
      showHome(); await wait(300); showSetup();
      let note = null; for(let k = 0; k < 40 && !note; k++){ await wait(250); note = document.querySelector('.penal-note-sheet'); }
      const out = { opts, note: note ? note.textContent : null, seen: localStorage.getItem('class26e.penal124256.seen') };
      document.querySelectorAll('.invite-overlay').forEach(x => x.remove());
      return out; }""")
    short = [o for o in pop["opts"] if "124\u2013256" in o]
    check("the pop-up's slides choice says 116 questions", len(short) == 1 and "116 questions" in short[0], pop["opts"])
    check("a device that saw the 55-124 note is shown the 124-256 one, with the count, once",
          bool(pop["note"]) and "124\u2013256" in pop["note"] and "116 questions" in pop["note"] and pop["seen"] == "1", pop)
    ctx.close()
    # nothing that was in the bank moves: ab75270 beside this build
    try:
        old = _sp.run(["git", "-C", ROOT, "show", "ab75270:index.html"], capture_output=True, check=True).stdout.decode("utf-8")
    except Exception as e:
        check("ab75270 is in this repo to compare against", False, str(e)[:120]); return
    ob = INSET_RE.sub(lambda m: "0px", old).replace("let fbDb = null;", "let fbDb = null;" + FIRESTORE_STUB, 1)
    ctx = br.new_context(viewport={"width": 440, "height": 956})
    pg = ctx.new_page()
    pg.route("**/index.html", lambda rr: rr.fulfill(status=200, headers={"content-type": "text/html; charset=utf-8"}, body=ob))
    pg.route("**/version.json*", lambda rr: rr.fulfill(status=200, headers={"content-type": "application/json"}, body='{"build":"x","frameId":"","note":""}'))
    pg.goto(URL); pg.wait_for_timeout(2600)
    was = pg.evaluate(Q)
    ctx.close()
    extra = r["keys"][len(was["keys"]):]
    # BUILD 325 adds 358-364 after 351-357.
    added = sorted(PENAL_REPEATS) + list(range(358, 365))
    check("every key that was in the bank is byte-identical and in place; only the copies are new",
          r["keys"][:len(was["keys"])] == was["keys"] and extra == ["Penal Code|%d|" % c + k.split("|")[2] for c, k in zip(added, extra)]
          and len(extra) == len(added), [len(r["keys"]), len(was["keys"])])
    check("and the next 400 daily questions are the same ones", r["daily"] == was["daily"],
          sum(1 for a, b in zip(r["daily"], was["daily"]) if a != b))



