def check_b324_inspect_flick(br):
    """Build 324. A badge in your hand spins on a flick and coasts round to a
    face. The pointer's draw frame and the spin's own loop shared one rAF
    handle, and release() only started the loop if no frame was pending: a
    flick whose last move and release land in the same frame - which a fast
    flick on a phone can deliver - left the draw frame pending, so the loop
    never started and the badge froze mid-coast at whatever angle it had
    reached, "coast" for ever. Found on a recording that did exactly that.
    Real moves a frame apart, then the last move and the release in one
    task: the badge has to come to rest on a face. Fails on 8ad9457."""
    print("\n324fl. a flick whose last move and release share a frame still spins the badge round to a face")
    ctx, pg = booted(br, 440, 956, seed=USED_ACCOUNT)
    r = pg.evaluate("""async () => { const wait = ms => new Promise(r => setTimeout(r, ms)); const out = {};
      const units = unitsInTeachingOrder(); store.unitPerfects = {}; units.forEach(u => store.unitPerfects[u] = badgeThresholdFor(u));
      store.seenUnlocks = store.seenUnlocks || { chars: [], banners: [], themes: [], badges: [] }; store.seenUnlocks.badges = units.slice();
      store.badgeCleanedAt = {}; units.forEach(u => store.badgeCleanedAt[u] = Date.now());
      store.rankMapFx244 = true; store.rankMapSeen = TIER_ORDER_FULL.indexOf(rankOf(store));
      store.pendingBadgeUnlocks = []; theme.muteBanners = true; theme.reduceMotion = false; applyTheme();
      document.querySelectorAll('#pushing-update,#intro-pop,.app-banner,.daily-alert,.update-banner').forEach(n => n.remove());
      showRanksScreen('badges'); await wait(1800);
      const cell = document.querySelector('.badges-tab .ncase-cell'); cell.scrollIntoView({ block: 'center', behavior: 'instant' }); await wait(300);
      cell.click();
      for(let i = 0; i < 40 && !(badgeInspectNow && badgeInspectNow.state().mode === 'idle'); i++) await wait(100);
      await wait(1500);
      const hit = document.querySelector('.binspect-hit'); const f = document.querySelector('.binspect-float').getBoundingClientRect();
      const x0 = f.left + f.width * .2, y = f.top + f.height / 2, w = f.width;
      const ev = (type, x) => hit.dispatchEvent(new PointerEvent(type, { pointerId: 7, pointerType: 'touch', isPrimary: true, bubbles: true, clientX: x, clientY: y, button: 0, buttons: type === 'pointerup' ? 0 : 1 }));
      ev('pointerdown', x0);
      let x = x0;
      for(let i = 1; i <= 5; i++){ await new Promise(r => requestAnimationFrame(r)); x = x0 + i * w * .07; ev('pointermove', x); }
      /* the last move and the release in the same task: no frame between them */
      await wait(6); ev('pointermove', x + w * .07); ev('pointerup', x + w * .07);
      out.after = badgeInspectNow.state();
      await wait(4000);
      out.rest = badgeInspectNow.state();
      try{ badgeInspectNow.teardown(); }catch(e){}
      return out; }""")
    a, z = r.get("after") or {}, r.get("rest") or {}
    th = z.get("theta")
    check("the flick sets it spinning (coast) on release", a.get("mode") == "coast", a)
    check("...and it comes to rest on a face (idle, a multiple of 180 degrees), not frozen mid-turn",
          z.get("mode") == "idle" and th is not None and abs(((th % 180) + 180) % 180) < 0.01 and abs(th) >= 180, z)
    ctx.close()


def check_b324_roomchat_focus(br):
    """Build 324. Cutscene focus (b320c: "you shouldn't be able to chat at
    all during any type of cutscene") slid the chat dock's button UP out of
    frame and gave a room's chat button the tab bar's slide DOWN. The room
    chat button is top-anchored everywhere it appears - beside the dock's
    button, or in the dock's own corner over the race leaderboard - so
    "down by its own height and a bit" left it 102px lower, still on screen
    over the leaderboard cutscene, a chat button you could see and not tap.
    Found on a recording of a race against Nova. During focus both chat
    buttons are above the top edge and take no tap; after it both are back
    where they were. Fails on ebf5d4a (the room's button sits in frame)."""
    print("\n324rc. cutscene focus takes a room's chat button out of frame too (it is top-anchored, so it leaves upward)")
    for race in (False, True):
        ctx, pg = booted(br, 440, 956, seed=USED_ACCOUNT)
        r = pg.evaluate("""async (race) => { const wait = ms => new Promise(r => setTimeout(r, ms)); const out = {};
          document.querySelectorAll('#pushing-update,#intro-pop,.nova-talk').forEach(n => n.remove());
          showHome(); await wait(400);
          /* MOVED IN 327 (round 6): out of sight, as the waiting results build it - a chat on the page has no Room button now */
          const rch = document.createElement('div'); rch.className = 'roomchat-host'; rch.hidden = true;
          const chat = document.createElement('section'); chat.className = 'vroom-chat'; rch.appendChild(chat); stage.firstElementChild.appendChild(rch);
          if(race){ const c = document.createElement('div'); c.id = 'vroom-race-cut'; document.body.appendChild(c); }
          mountRoomChatFab(); await wait(300);
          const box = s => { const e = document.querySelector(s); if(!e) return null; const b = e.getBoundingClientRect();
            const cs = getComputedStyle(e); return { top: Math.round(b.top), bottom: Math.round(b.bottom), pe: cs.pointerEvents, vis: cs.visibility }; };
          out.before = { fab: box('#roomchat-fab'), dock: box('#chatdock-btn') };
          setCutsceneFocus(true); await wait(900);
          out.during = { fab: box('#roomchat-fab'), dock: box('#chatdock-btn') };
          setCutsceneFocus(false); await wait(1200);
          out.after = { fab: box('#roomchat-fab'), dock: box('#chatdock-btn') };
          document.getElementById('vroom-race-cut')?.remove();
          return out; }""", race)
        b, d, a = r["before"]["fab"], r["during"]["fab"], r["after"]["fab"]
        where = "over the race leaderboard" if race else "beside the dock's button"
        # (over the race leaderboard the cutscene itself switches focus on, and holds it while it is up)
        if not race:
            check("%s: the room's chat button is in frame before a cutscene" % where, b and b["top"] >= 0 and b["bottom"] <= 956, b)
        check("%s: during the cutscene it is above the top edge and takes no tap" % where,
              d and (d["bottom"] <= 0 or d["vis"] == "hidden") and d["pe"] == "none", d)
        dd = r["during"]["dock"]
        check("%s: the dock's button leaves the same way" % where, dd is None or dd["bottom"] <= 0 or dd["vis"] == "hidden", dd)
        if not race:
            check("%s: after it, it is back where it was" % where, a and b and abs(a["top"] - b["top"]) <= 1, {"before": b, "after": a})
        ctx.close()


def check_b324_merge_quiet(br):
    """Build 324. Nova's weekly recap merged weekStats/prevWeekStats by
    comparing the raw copy on this device with the cleaned merge of it, so
    the two never stringified alike and EVERY live snapshot reported a
    gain: Home re-mounted under any open sheet (the chat's Invite sheet
    shut itself a second after inviting) and the account re-pushed. The
    same stats merged twice must gain nothing; a higher count from the
    other device must still gain. Fails on 685dc7b."""
    print("\n324m. the weekly counters merge quietly when nothing changed")
    ctx, pg = booted(br, 440, 956, seed=USED_ACCOUNT)
    r = pg.evaluate("""() => {
      const k = '2026-10-12';
      const raw = { k, t: 3 };
      store.weekStats = Object.assign({}, raw); store.prevWeekStats = { k: '2026-10-05', t: 9, h: 2 };
      const same = JSON.parse(JSON.stringify(store));
      const quiet = mergeSameAccount(store, same).gained;
      const again = mergeSameAccount(store, JSON.parse(JSON.stringify(store))).gained;
      const more = JSON.parse(JSON.stringify(store)); more.weekStats = { k, t: 7 };
      const loud = mergeSameAccount(store, more).gained;
      return { quiet, again, loud, t: store.weekStats && store.weekStats.t }; }""")
    check("the same week stats merged in gain nothing (no Home re-mount, no re-push)", r["quiet"] is False and r["again"] is False, r)
    check("a higher count from the other device still gains, and is kept", r["loud"] is True and r["t"] == 7, r)
    ctx.close()


def check_b324v3_tug(br):
    """Build 324 (b324v3). Madison, asked whether to slow Nova slightly in
    Tug of War and Battle: "Yes". At 2-4s an answer a locked-in student (4s,
    97%) beat him about one match in thirty there, since both modes reward
    getting through questions. He now takes 0.75s longer per answer in those
    two modes only; a Race is unchanged. Asserted through the driver itself:
    with the clock held just before and just after each answer is due, the
    first answer lands at plan + 750ms in Tug and Battle and at plan in a
    Race. Fails on 61937c4 (no per-mode timing)."""
    print("\n324v3. Nova is 0.75s slower in Tug of War and Battle, and only there")
    ctx, pg = booted(br, 440, 956, seed=USED_ACCOUNT, init=_ROOM_FAKE)
    errs = []
    pg.on("pageerror", lambda e: errs.append(str(e)))
    r = pg.evaluate("""() => { const out = { extra: typeof NOVA_VR_TEAM_EXTRA_MS === 'number' ? NOVA_VR_TEAM_EXTRA_MS : null };
      if(typeof novaVrPlan !== 'function') return out;
      window.firebase = window.firebase || { firestore: { FieldValue: { delete: () => ({ _delete: true }), arrayUnion: v => ({ __au: v }) } } };
      const realNow = Date.now, realWrite = novaVrWrite; const writes = [];
      novaVrWrite = p => writes.push(Object.keys(p));
      const start = realNow.call(Date) + 100000;
      const plan = novaVrPlan(424242, 60);
      const mk = game => ({ game, pool: Array.from({ length: 50 }, (_, i) => i), plan, pos: 0, correct: 0, pull: 0, streak: 0, sinceGrant: 0,
        held: null, useAt: 0, shownAt: start, startAt: start, frozenUntil: 0, flippedUntil: 0, seenFx: new Set(), done: false });
      const room = game => ({ game, startAt: start, units: [], participants: { me: { name: 'Me', seen: start }, nova: { name: 'Nova', nova: true, seen: start } },
        tug: { over: false, count: 50, teams: { me: 'a', nova: 'b' }, progress: {} }, battle: { over: false, log: [], teams: { me: 'a', nova: 'b' }, progress: {} } });
      const step = { race: novaVrRaceStep, tug: novaVrTugStep, battle: novaVrBattleStep };
      const at = (game, dt) => { const m = mk(game); Date.now = () => start + dt; try{ step[game](m, room(game)); } finally { Date.now = realNow; } return m.pos; };
      out.ms0 = plan.ms[0];
      ['race', 'tug', 'battle'].forEach(g => {
        out[g] = { atPlan: at(g, plan.ms[0] + 5), justBefore750: at(g, plan.ms[0] + 740), at750: at(g, plan.ms[0] + 760) };
      });
      novaVrWrite = realWrite;
      return out; }""")
    check("Nova's extra time in Tug of War and Battle is 750ms", r.get("extra") == 750, r.get("extra"))
    if r.get("extra") is not None and "race" in r:
        check("a Race is unchanged: his first answer lands at its planned 2-4s",
              r["race"] == {"atPlan": 1, "justBefore750": 1, "at750": 1}, r)
        check("Tug of War: his first answer lands 750ms after its planned time, not before",
              r["tug"] == {"atPlan": 0, "justBefore750": 0, "at750": 1}, r)
        check("Battle: the same 750ms",
              r["battle"] == {"atPlan": 0, "justBefore750": 0, "at750": 1}, r)
    check("no page errors", not errs, errs[:3])
    ctx.close()

